static int run_ownerless_sql_internal_command(int argc, char **argv) {
    const int initialize_result = run_ownerless_sql_internal_initialize(argc, argv);

    if (initialize_result >= 0) {
        return initialize_result;
    }
    return run_ownerless_sql_internal_test_case(argc, argv);
}

static int run_ownerless_sql_internal_initialize(int argc, char **argv) {
    if (argc != 4 || strcmp(argv[1], OWNERLESS_SQL_INTERNAL_INITIALIZE_ARG) != 0) {
        return -1;
    }

    const open_database_paths paths = {
        .database_path = argv[2],
        .runtime_root = argv[3],
    };
    initialize_database_in_process(paths);
    return 0;
}

static int run_ownerless_sql_internal_test_case(int argc, char **argv) {
    const size_t prefix_length = strlen(OWNERLESS_SQL_INTERNAL_TEST_CASE_ARG);
    const char *argument;
    char *end = NULL;
    unsigned long test_case_index;

    if (argc != 2) {
        return -1;
    }
    argument = argv[1];
    if (strncmp(argument, OWNERLESS_SQL_INTERNAL_TEST_CASE_ARG, prefix_length) != 0) {
        return -1;
    }

    errno = 0;
    test_case_index = strtoul(argument + prefix_length, &end, 10);
    assert(errno == 0);
    assert(end != argument + prefix_length);
    assert(*end == '\0');
    assert(
        test_case_index < sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0])
    );
    ownerless_sql_test_cases[test_case_index].run();
    return 0;
}

static int run_ownerless_sql_case_count_command(int argc, char **argv) {
    if (argc != 2 || strcmp(argv[1], "sql-case-count") != 0) {
        return -1;
    }

    printf("%zu\n", sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]));
    fflush(stdout);
    return 0;
}

static int run_ownerless_sql_case_command(int argc, char **argv) {
    size_t test_case_index;

    if (argc != 3 || strcmp(argv[1], "sql-case") != 0) {
        return -1;
    }
    if (find_ownerless_sql_test_case(argv[2], &test_case_index) != 0) {
        fprintf(stderr, "unknown ownerless SQL case: %s\n", argv[2]);
        fflush(stderr);
        return 2;
    }

    run_ownerless_sql_test_case(test_case_index);
    return 0;
}

static int run_ownerless_sql_shard_command(int argc, char **argv) {
    size_t shard_index;
    size_t shard_count;

    if (argc != 4 || strcmp(argv[1], "sql-shard") != 0) {
        return -1;
    }
    if (parse_ownerless_sql_shard_argument(argv[2], &shard_index) != 0 ||
        parse_ownerless_sql_shard_argument(argv[3], &shard_count) != 0 || shard_count == 0U ||
        shard_index >= shard_count) {
        fprintf(stderr, "invalid ownerless SQL shard arguments\n");
        fflush(stderr);
        return 2;
    }

    run_ownerless_sql_test_shard(shard_index, shard_count);
    return 0;
}

static int run_ownerless_sql_weighted_shard_command(int argc, char **argv) {
    size_t shard_index;
    size_t shard_count;

    if (argc != 4 || strcmp(argv[1], "sql-weighted-shard") != 0) {
        return -1;
    }
    if (parse_ownerless_sql_shard_argument(argv[2], &shard_index) != 0 ||
        parse_ownerless_sql_shard_argument(argv[3], &shard_count) != 0 || shard_count == 0U ||
        shard_count > MYLITE_TEST_OWNERLESS_SQL_MAX_WEIGHTED_SHARDS || shard_index >= shard_count) {
        fprintf(stderr, "invalid ownerless SQL weighted shard arguments\n");
        fflush(stderr);
        return 2;
    }

    run_ownerless_sql_weighted_shard(shard_index, shard_count);
    return 0;
}

static int parse_ownerless_sql_shard_argument(const char *argument, size_t *out_value) {
    char *end = NULL;
    unsigned long value;

    errno = 0;
    value = strtoul(argument, &end, 10);
    if (errno != 0 || end == argument || *end != '\0') {
        return -1;
    }

    *out_value = (size_t)value;
    return 0;
}

static int find_ownerless_sql_test_case(const char *argument, size_t *out_index) {
    const size_t test_case_count =
        sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]);
    size_t test_case_index;

    assert(argument != NULL);
    assert(out_index != NULL);
    if (parse_ownerless_sql_shard_argument(argument, &test_case_index) == 0) {
        if (test_case_index >= test_case_count) {
            return -1;
        }
        *out_index = test_case_index;
        return 0;
    }

    for (test_case_index = 0U; test_case_index < test_case_count; ++test_case_index) {
        if (strcmp(argument, ownerless_sql_test_cases[test_case_index].name) == 0) {
            *out_index = test_case_index;
            return 0;
        }
    }
    return -1;
}

static void run_all_ownerless_sql_tests(void) {
    const size_t test_case_count =
        sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]);

    for (size_t test_case_index = 0U; test_case_index < test_case_count; ++test_case_index) {
        run_ownerless_sql_test_case(test_case_index);
    }
}

static void run_ownerless_sql_test_shard(size_t shard_index, size_t shard_count) {
    const size_t test_case_count =
        sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]);

    fprintf(
        stderr,
        "ownerless-sql shard start index=%zu count=%zu cases=%zu\n",
        shard_index,
        shard_count,
        test_case_count
    );
    fflush(stderr);
    for (size_t test_case_index = shard_index; test_case_index < test_case_count;
         test_case_index += shard_count) {
        run_ownerless_sql_test_case(test_case_index);
    }
    fprintf(stderr, "ownerless-sql shard pass index=%zu count=%zu\n", shard_index, shard_count);
    fflush(stderr);
}

static unsigned long long u64_ull(uint64_t value) {
    return (unsigned long long)value;
}

static void run_ownerless_sql_weighted_shard(size_t shard_index, size_t shard_count) {
    const size_t test_case_count =
        sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]);
    size_t *assignments;
    unsigned shard_weights[MYLITE_TEST_OWNERLESS_SQL_MAX_WEIGHTED_SHARDS] = {0U};

    assert(shard_count > 0U);
    assert(shard_count <= MYLITE_TEST_OWNERLESS_SQL_MAX_WEIGHTED_SHARDS);
    assert(shard_index < shard_count);
    assignments = (size_t *)calloc(test_case_count, sizeof(assignments[0]));
    assert(assignments != NULL);
    assign_ownerless_sql_weighted_shards(shard_count, assignments, shard_weights);
    fprintf(
        stderr,
        "ownerless-sql weighted-shard start index=%zu count=%zu cases=%zu weight=%u\n",
        shard_index,
        shard_count,
        test_case_count,
        shard_weights[shard_index]
    );
    fflush(stderr);
    for (size_t test_case_index = 0U; test_case_index < test_case_count; ++test_case_index) {
        if (assignments[test_case_index] == shard_index) {
            run_ownerless_sql_test_case(test_case_index);
        }
    }
    fprintf(
        stderr,
        "ownerless-sql weighted-shard pass index=%zu count=%zu weight=%u\n",
        shard_index,
        shard_count,
        shard_weights[shard_index]
    );
    fflush(stderr);
    free(assignments);
}

static unsigned estimate_ownerless_sql_test_case_weight(const char *name) {
    unsigned weight = 1U;

    assert(name != NULL);
    if (strstr(name, "stress") != NULL) {
        weight += 5U;
    }
    if (strstr(name, "pressure") != NULL || strstr(name, "blob") != NULL ||
        strstr(name, "compressed") != NULL || strstr(name, "large") != NULL) {
        weight += 4U;
    }
    if (strstr(name, "crashed") != NULL || strstr(name, "crash") != NULL ||
        strstr(name, "rebuild") != NULL || strstr(name, "replay") != NULL ||
        strstr(name, "checkpoint") != NULL) {
        weight += 3U;
    }
    if (strstr(name, "ddl") != NULL || strstr(name, "dictionary") != NULL ||
        strstr(name, "alter") != NULL || strstr(name, "index") != NULL ||
        strstr(name, "key") != NULL || strstr(name, "column") != NULL ||
        strstr(name, "schema") != NULL || strstr(name, "view") != NULL ||
        strstr(name, "trigger") != NULL || strstr(name, "foreign_key") != NULL ||
        strstr(name, "generated") != NULL || strstr(name, "table") != NULL) {
        weight += 2U;
    }
    if (strstr(name, "multi") != NULL || strstr(name, "deep") != NULL ||
        strstr(name, "cyclic") != NULL || strstr(name, "instant") != NULL ||
        strstr(name, "serializable") != NULL) {
        weight += 1U;
    }
    return weight;
}

static void assign_ownerless_sql_weighted_shards(
    size_t shard_count,
    size_t *assignments,
    unsigned *shard_weights
) {
    const size_t test_case_count =
        sizeof(ownerless_sql_test_cases) / sizeof(ownerless_sql_test_cases[0]);

    assert(shard_count > 0U);
    assert(shard_count <= MYLITE_TEST_OWNERLESS_SQL_MAX_WEIGHTED_SHARDS);
    assert(assignments != NULL);
    assert(shard_weights != NULL);
    for (size_t test_case_index = 0U; test_case_index < test_case_count; ++test_case_index) {
        size_t lightest_shard = 0U;
        unsigned test_weight =
            estimate_ownerless_sql_test_case_weight(ownerless_sql_test_cases[test_case_index].name);

        for (size_t candidate = 1U; candidate < shard_count; ++candidate) {
            if (shard_weights[candidate] < shard_weights[lightest_shard]) {
                lightest_shard = candidate;
            }
        }
        assignments[test_case_index] = lightest_shard;
        shard_weights[lightest_shard] += test_weight;
    }
}

static void run_ownerless_sql_test_case(size_t test_case_index) {
    const ownerless_sql_test_case *test_case = &ownerless_sql_test_cases[test_case_index];
    char argument[64];
    int argument_length;
    pid_t child;
    int child_status = 0;
    int wait_result;
    time_t start_time;
    time_t end_time;

    assert(ownerless_sql_test_program_path != NULL);
    start_time = time(NULL);
    fprintf(
        stderr,
        "ownerless-sql case start index=%zu name=%s\n",
        test_case_index,
        test_case->name
    );
    fflush(stderr);
    child = fork();
    assert(child >= 0);
    if (child == 0) {
        assert(setpgid(0, 0) == 0);
        argument_length = snprintf(
            argument,
            sizeof(argument),
            "%s%zu",
            OWNERLESS_SQL_INTERNAL_TEST_CASE_ARG,
            test_case_index
        );
        assert(argument_length > 0);
        assert((size_t)argument_length < sizeof(argument));
        execlp(
            ownerless_sql_test_program_path,
            ownerless_sql_test_program_path,
            argument,
            (char *)NULL
        );
        perror("execlp");
        _exit(MYLITE_TEST_CHILD_EXEC_FAILED);
    }
    if (setpgid(child, child) != 0) {
        assert(errno == EACCES || errno == ESRCH);
    }
    wait_result = wait_for_child_with_timeout(
        child,
        MYLITE_TEST_OWNERLESS_SQL_CASE_TIMEOUT_MS,
        &child_status
    );
    if (wait_result == 0) {
        fprintf(
            stderr,
            "ownerless-sql case timeout index=%zu name=%s pid=%ld timeout_seconds=%u\n",
            test_case_index,
            test_case->name,
            (long)child,
            MYLITE_TEST_OWNERLESS_SQL_CASE_TIMEOUT_MS / 1000U
        );
        fflush(stderr);
        dump_ownerless_sql_timeout_process_state(test_case_index, test_case->name, child);
        if (kill(-child, SIGKILL) != 0 && errno != ESRCH) {
            fprintf(
                stderr,
                "ownerless-sql case timeout process-group SIGKILL failed index=%zu name=%s "
                "pid=%ld errno=%d\n",
                test_case_index,
                test_case->name,
                (long)child,
                errno
            );
            fflush(stderr);
        }
        if (kill(child, SIGKILL) != 0 && errno != ESRCH) {
            fprintf(
                stderr,
                "ownerless-sql case timeout SIGKILL failed index=%zu name=%s pid=%ld errno=%d\n",
                test_case_index,
                test_case->name,
                (long)child,
                errno
            );
            fflush(stderr);
        }
        do {
            pid_t reap_result = waitpid(child, &child_status, 0);

            if (reap_result == child) {
                fprintf(
                    stderr,
                    "ownerless-sql case timeout child index=%zu name=%s pid=%ld status=%d "
                    "exited=%d exit=%d signaled=%d signal=%d\n",
                    test_case_index,
                    test_case->name,
                    (long)child,
                    child_status,
                    WIFEXITED(child_status),
                    WIFEXITED(child_status) ? WEXITSTATUS(child_status) : -1,
                    WIFSIGNALED(child_status),
                    WIFSIGNALED(child_status) ? WTERMSIG(child_status) : -1
                );
                break;
            }
            if (errno != EINTR) {
                fprintf(
                    stderr,
                    "ownerless-sql case timeout reap failed index=%zu name=%s pid=%ld errno=%d\n",
                    test_case_index,
                    test_case->name,
                    (long)child,
                    errno
                );
                break;
            }
        } while (1);
        fflush(stderr);
        assert(0);
    }
    if (wait_result < 0) {
        fprintf(
            stderr,
            "ownerless-sql case waitpid failed index=%zu name=%s pid=%ld errno=%d\n",
            test_case_index,
            test_case->name,
            (long)child,
            errno
        );
        fflush(stderr);
    }
    assert(wait_result > 0);
    if (!WIFEXITED(child_status) || WEXITSTATUS(child_status) != 0) {
        fprintf(
            stderr,
            "ownerless-sql case child index=%zu name=%s pid=%ld status=%d exited=%d exit=%d "
            "signaled=%d signal=%d\n",
            test_case_index,
            test_case->name,
            (long)child,
            child_status,
            WIFEXITED(child_status),
            WIFEXITED(child_status) ? WEXITSTATUS(child_status) : -1,
            WIFSIGNALED(child_status),
            WIFSIGNALED(child_status) ? WTERMSIG(child_status) : -1
        );
        fflush(stderr);
    }
    assert(WIFEXITED(child_status));
    assert(WEXITSTATUS(child_status) == 0);
    end_time = time(NULL);
    fprintf(
        stderr,
        "ownerless-sql case pass index=%zu name=%s seconds=%lld\n",
        test_case_index,
        test_case->name,
        (long long)(end_time - start_time)
    );
    fflush(stderr);
}

static void run_ownerless_crash_tail_test(ownerless_test_fn test_fn) {
    pid_t child = fork();

    assert(test_fn != NULL);
    assert(child >= 0);
    if (child == 0) {
        test_fn();
        _exit(MYLITE_TEST_CHILD_OK);
    }
    wait_for_child(child);
}

static void test_two_processes_update_different_innodb_rows(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-different-rows.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t first_child;
    pid_t second_child;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    first_child = fork();
    assert(first_child >= 0);
    if (first_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        update_first_row_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    second_child = fork();
    assert(second_child >= 0);
    if (second_child == 0) {
        update_second_row(paths);
    }

    signal_pipe(release_pipe[1]);
    wait_for_child(first_child);
    wait_for_child(second_child);
    assert_total_value(paths, 33U);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_two_processes_update_same_innodb_row(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-same-row.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t first_child;
    pid_t second_child;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    first_child = fork();
    assert(first_child >= 0);
    if (first_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        update_first_row_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    second_child = fork();
    assert(second_child >= 0);
    if (second_child == 0) {
        update_first_row_by_two(paths);
    }

    assert(wait_for_concurrency_ownerless_write_waiting_count(database_path, 1U, 5000U) >= 1U);
    signal_pipe(release_pipe[1]);
    wait_for_child(first_child);
    wait_for_child(second_child);
    assert(wait_for_concurrency_ownerless_write_waiting_count(database_path, 0U, 5000U) == 0U);
    assert_total_value(paths, 33U);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_two_processes_update_different_innodb_tables(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-different-tables.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int first_ready_pipe[2];
    int first_release_pipe[2];
    int second_ready_pipe[2];
    int second_release_pipe[2];
    pid_t first_child;
    pid_t second_child;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(first_ready_pipe) == 0);
    assert(pipe(first_release_pipe) == 0);
    assert(pipe(second_ready_pipe) == 0);
    assert(pipe(second_release_pipe) == 0);

    first_child = fork();
    assert(first_child >= 0);
    if (first_child == 0) {
        close(first_ready_pipe[0]);
        close(first_release_pipe[1]);
        close(second_ready_pipe[0]);
        close(second_ready_pipe[1]);
        close(second_release_pipe[0]);
        close(second_release_pipe[1]);
        update_first_table_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = first_ready_pipe[1],
                .release_read_fd = first_release_pipe[0],
            }
        );
    }

    close(first_ready_pipe[1]);
    close(first_release_pipe[0]);
    wait_for_pipe(first_ready_pipe[0]);

    second_child = fork();
    assert(second_child >= 0);
    if (second_child == 0) {
        close(second_ready_pipe[0]);
        close(second_release_pipe[1]);
        close(first_ready_pipe[0]);
        close(first_release_pipe[1]);
        update_second_table_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = second_ready_pipe[1],
                .release_read_fd = second_release_pipe[0],
            }
        );
    }

    close(second_ready_pipe[1]);
    close(second_release_pipe[0]);
    wait_for_pipe(second_ready_pipe[0]);
    signal_pipe(second_release_pipe[1]);
    signal_pipe(first_release_pipe[1]);
    wait_for_child(second_child);
    wait_for_child(first_child);
    assert_table_values(paths);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static unsigned wait_for_commit_race_ready_barrier(
    const char *database_path,
    int ready_pipes[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT][2],
    const pid_t workers[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT],
    uint64_t *out_ownerless_waiting_count
) {
    const uint64_t deadline_ms =
        monotonic_milliseconds() + MYLITE_TEST_COMMIT_RACE_READY_TIMEOUT_MS;
    int ready_seen[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT] = {0};
    unsigned ready_count = 0U;

    *out_ownerless_waiting_count = 0U;
    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        int pipe_flags = fcntl(ready_pipes[worker_id][0], F_GETFL, 0);

        assert(pipe_flags >= 0);
        assert(fcntl(ready_pipes[worker_id][0], F_SETFL, pipe_flags | O_NONBLOCK) == 0);
    }

    for (;;) {
        for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT;
             ++worker_id) {
            char value = '\0';
            ssize_t bytes_read;

            if (ready_seen[worker_id]) {
                continue;
            }
            bytes_read = read(ready_pipes[worker_id][0], &value, sizeof(value));
            if (bytes_read == (ssize_t)sizeof(value)) {
                assert(value == 'x');
                assert(close(ready_pipes[worker_id][0]) == 0);
                ready_pipes[worker_id][0] = -1;
                ready_seen[worker_id] = 1;
                ++ready_count;
                continue;
            }
            if (bytes_read == 0) {
                fprintf(
                    stderr,
                    "commit-race worker %u closed ready pipe before barrier\n",
                    worker_id + 1U
                );
                fflush(stderr);
                assert(bytes_read != 0);
            }
            if (bytes_read < 0) {
                assert(errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR);
            }
        }

        if (ready_count == MYLITE_TEST_COMMIT_RACE_WORKER_COUNT) {
            return ready_count;
        }

        if (ready_count > 0U) {
            *out_ownerless_waiting_count =
                read_concurrency_innodb_lock_waiting_count(database_path) +
                read_concurrency_page_write_lock_waiting_count(database_path);
            if (ready_count + *out_ownerless_waiting_count >=
                MYLITE_TEST_COMMIT_RACE_WORKER_COUNT) {
                return ready_count;
            }
        }

        if (monotonic_milliseconds() >= deadline_ms) {
            fprintf(
                stderr,
                "commit-race ready barrier timed out: ready=%u ownerless_waiting=%llu\n",
                ready_count,
                (unsigned long long)*out_ownerless_waiting_count
            );
            fflush(stderr);
            for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT;
                 ++worker_id) {
                int child_status = 0;
                const pid_t wait_result = waitpid(workers[worker_id], &child_status, WNOHANG);

                if (wait_result == workers[worker_id]) {
                    fprintf(
                        stderr,
                        "commit-race worker %u exited before release: status=%d exited=%d "
                        "exit=%d signaled=%d signal=%d\n",
                        worker_id + 1U,
                        child_status,
                        WIFEXITED(child_status),
                        WIFEXITED(child_status) ? WEXITSTATUS(child_status) : -1,
                        WIFSIGNALED(child_status),
                        WIFSIGNALED(child_status) ? WTERMSIG(child_status) : -1
                    );
                }
            }
            fflush(stderr);
            assert(ready_count == MYLITE_TEST_COMMIT_RACE_WORKER_COUNT);
        }

        sleep_microseconds(MYLITE_TEST_WAIT_POLL_INTERVAL_US);
    }
}

static void test_ownerless_concurrent_transaction_commits(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-commit-race.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int open_ready_pipes[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT][2];
    int update_release_pipes[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT][2];
    int updated_ready_pipes[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT][2];
    int commit_release_pipes[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT][2];
    pid_t workers[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT];
    mylite_db *db;
    char sql[192];
    unsigned long long expected_sum = 0U;
    unsigned ready_count;
    uint64_t ownerless_waiting_count;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE);
    for (unsigned table_id = 1U; table_id <= MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++table_id) {
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "CREATE TABLE app.ownerless_commit_race_%u ("
                "id INT NOT NULL PRIMARY KEY, "
                "value INT NOT NULL"
                ") ENGINE=InnoDB",
                table_id
            ) > 0
        );
        exec_ok(db, sql);
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "INSERT INTO app.ownerless_commit_race_%u VALUES (1, 0)",
                table_id
            ) > 0
        );
        exec_ok(db, sql);
        expected_sum += table_id;
    }
    assert(mylite_close(db) == MYLITE_OK);

    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        assert(pipe(open_ready_pipes[worker_id]) == 0);
        assert(pipe(update_release_pipes[worker_id]) == 0);
        assert(pipe(updated_ready_pipes[worker_id]) == 0);
        assert(pipe(commit_release_pipes[worker_id]) == 0);
    }

    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        workers[worker_id] = fork();
        assert(workers[worker_id] >= 0);
        if (workers[worker_id] == 0) {
            for (unsigned pipe_id = 0U; pipe_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++pipe_id) {
                if (pipe_id == worker_id) {
                    close(open_ready_pipes[pipe_id][0]);
                    close(update_release_pipes[pipe_id][1]);
                    close(updated_ready_pipes[pipe_id][0]);
                    close(commit_release_pipes[pipe_id][1]);
                } else {
                    close(open_ready_pipes[pipe_id][0]);
                    close(open_ready_pipes[pipe_id][1]);
                    close(update_release_pipes[pipe_id][0]);
                    close(update_release_pipes[pipe_id][1]);
                    close(updated_ready_pipes[pipe_id][0]);
                    close(updated_ready_pipes[pipe_id][1]);
                    close(commit_release_pipes[pipe_id][0]);
                    close(commit_release_pipes[pipe_id][1]);
                }
            }
            commit_race_update_row_after_signal(
                paths,
                worker_id + 1U,
                worker_id + 1U,
                (commit_race_child_pipes){
                    .open_ready_write_fd = open_ready_pipes[worker_id][1],
                    .update_release_read_fd = update_release_pipes[worker_id][0],
                    .updated_ready_write_fd = updated_ready_pipes[worker_id][1],
                    .commit_release_read_fd = commit_release_pipes[worker_id][0],
                }
            );
        }
    }

    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        close(open_ready_pipes[worker_id][1]);
        close(update_release_pipes[worker_id][0]);
        close(updated_ready_pipes[worker_id][1]);
        close(commit_release_pipes[worker_id][0]);
    }
    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        wait_for_pipe(open_ready_pipes[worker_id][0]);
    }
    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        signal_pipe(update_release_pipes[worker_id][1]);
    }
    ready_count = wait_for_commit_race_ready_barrier(
        database_path,
        updated_ready_pipes,
        workers,
        &ownerless_waiting_count
    );
    if (ready_count < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT) {
        assert(ready_count + ownerless_waiting_count >= MYLITE_TEST_COMMIT_RACE_WORKER_COUNT);
    }

    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        signal_pipe(commit_release_pipes[worker_id][1]);
    }
    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        wait_for_child(workers[worker_id]);
    }
    for (unsigned worker_id = 0U; worker_id < MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++worker_id) {
        if (updated_ready_pipes[worker_id][0] >= 0) {
            assert(close(updated_ready_pipes[worker_id][0]) == 0);
        }
    }
    assert(read_concurrency_innodb_lock_waiting_count(database_path) == 0U);
    assert(read_concurrency_page_write_lock_waiting_count(database_path) == 0U);
    {
        const uint64_t checkpoint_latest_lsn =
            read_concurrency_checkpoint_latest_lsn(database_path);
        const uint64_t checkpoint_visible_lsn =
            read_concurrency_checkpoint_visible_lsn(database_path);
        if (checkpoint_latest_lsn != 0U && checkpoint_visible_lsn == 0U) {
            fprintf(
                stderr,
                "expected ownerless commit-race checkpoint visible LSN after workers, "
                "latest=%llu visible=%llu\n",
                (unsigned long long)checkpoint_latest_lsn,
                (unsigned long long)checkpoint_visible_lsn
            );
        }
        assert(checkpoint_latest_lsn == 0U || checkpoint_visible_lsn != 0U);
    }

    assert_commit_race_total(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW, expected_sum);
    assert_commit_race_total(paths, MYLITE_OPEN_READWRITE, expected_sum);
    const uint64_t checkpoint_visible_lsn = assert_commit_race_recovery_anchors(database_path, 0U);

    remove_concurrency_shm(database_path);
    assert_commit_race_total(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW, expected_sum);
    assert_commit_race_recovery_anchors(database_path, checkpoint_visible_lsn);
    assert_commit_race_total(paths, MYLITE_OPEN_READWRITE, expected_sum);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

