static void test_ownerless_native_checkpoint_reclaims_page_log(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-native-checkpoint-reclaim.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    char insert_sql[176];

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_native_reclaim ("
        "id INT NOT NULL PRIMARY KEY, "
        "value VARBINARY(4000) NOT NULL"
        ") ENGINE=InnoDB"
    );
    for (unsigned id = 1U; id <= 32U; ++id) {
        assert(
            snprintf(
                insert_sql,
                sizeof(insert_sql),
                "INSERT INTO app.ownerless_native_reclaim VALUES (%u, REPEAT('z', 4000))",
                id
            ) > 0
        );
        exec_ok(db, insert_sql);
    }
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_native_reclaim") == 32U);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_native_reclaim") == 32U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_native_reclaim") == 32U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_checkpoint_lsn_record_recovers_from_torn_latest_slot(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-checkpoint-lsn-record.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    checkpoint_lsn_record best_record = {0};
    uint64_t legacy_latest_before;
    uint64_t visible_before;
    uint64_t visible_after;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_checkpoint_lsn_record ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_checkpoint_lsn_record VALUES (1, 10)");
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "UPDATE app.ownerless_checkpoint_lsn_record SET value = 11 WHERE id = 1");
    assert(query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_lsn_record") == 11U);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    assert(read_concurrency_checkpoint_lsn_records(database_path, &best_record));
    assert(best_record.generation > 1U);
    visible_before = best_record.visible_lsn;
    assert(visible_before > 0U);
    legacy_latest_before = read_concurrency_checkpoint_latest_lsn(database_path);
    assert(legacy_latest_before >= visible_before);

    corrupt_concurrency_checkpoint_latest_lsn_record(database_path);
    write_concurrency_checkpoint_legacy_lsns(database_path, 0U, 0U);
    assert(read_concurrency_checkpoint_latest_lsn(database_path) > 0U);
    remove_concurrency_shm(database_path);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_lsn_record") == 11U);
    exec_ok(db, "UPDATE app.ownerless_checkpoint_lsn_record SET value = 12 WHERE id = 1");
    assert(query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_lsn_record") == 12U);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    assert(read_concurrency_checkpoint_lsn_records(database_path, &best_record));
    visible_after = best_record.visible_lsn;
    assert(visible_after >= visible_before);
    assert(read_concurrency_checkpoint_latest_lsn(database_path) >= visible_after);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_lsn_record") == 12U);
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_checkpoint_lsn_noop_update_keeps_generation(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-checkpoint-noop-elision.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    checkpoint_lsn_record record = {0};
    uint64_t database_stats[OWNERLESS_TEST_DATABASE_PERF_STAT_COUNT] = {0};
    uint64_t latest_lsn;
    uint64_t visible_lsn;
    uint64_t initial_generation;
    uint64_t durable_generation;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_checkpoint_noop ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_checkpoint_noop VALUES (1, 10)");
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    assert(read_concurrency_checkpoint_lsn_records(database_path, &record));
    latest_lsn = record.latest_lsn;
    visible_lsn = record.visible_lsn;
    initial_generation = record.generation;
    assert(latest_lsn > 0U);
    assert(visible_lsn > 0U);
    assert(visible_lsn <= latest_lsn);
    assert(initial_generation > 0U);

    mylite_ownerless_database_set_perf_stats_enabled(1);
    mylite_ownerless_database_reset_perf_stats();
    assert(
        mylite_ownerless_database_test_update_checkpoint_lsn_repeated(
            database_path,
            latest_lsn,
            visible_lsn,
            0,
            3U
        ) == MYLITE_OK
    );
    assert(read_concurrency_checkpoint_lsn_records(database_path, &record));
    assert(record.generation == initial_generation);
    assert(record.latest_lsn == latest_lsn);
    assert(record.visible_lsn == visible_lsn);
    mylite_ownerless_database_read_perf_stats(
        database_stats,
        OWNERLESS_TEST_DATABASE_PERF_STAT_COUNT
    );
    assert(database_stats[OWNERLESS_TEST_DATABASE_PERF_STAT_CHECKPOINT_UPDATE_NOOP_ELIDED] == 3U);

    assert(
        mylite_ownerless_database_test_update_checkpoint_lsn_repeated(
            database_path,
            latest_lsn,
            visible_lsn,
            1,
            2U
        ) == MYLITE_OK
    );
    assert(read_concurrency_checkpoint_lsn_records(database_path, &record));
    assert(record.generation == initial_generation + 1U);
    assert(record.latest_lsn == latest_lsn);
    assert(record.visible_lsn == visible_lsn);
    durable_generation = record.generation;
    mylite_ownerless_database_read_perf_stats(
        database_stats,
        OWNERLESS_TEST_DATABASE_PERF_STAT_COUNT
    );
    assert(database_stats[OWNERLESS_TEST_DATABASE_PERF_STAT_CHECKPOINT_UPDATE_NOOP_ELIDED] == 4U);
    mylite_ownerless_database_set_perf_stats_enabled(0);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_noop WHERE id = 1") == 10U
    );
    exec_ok(db, "UPDATE app.ownerless_checkpoint_noop SET value = 11 WHERE id = 1");
    assert(
        query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_noop WHERE id = 1") == 11U
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    assert(read_concurrency_checkpoint_lsn_records(database_path, &record));
    assert(record.generation > durable_generation);
    assert(record.latest_lsn >= latest_lsn);
    assert(record.visible_lsn >= visible_lsn);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(
        query_unsigned(db, "SELECT value FROM app.ownerless_checkpoint_noop WHERE id = 1") == 11U
    );
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

