static void test_ownerless_native_file_op_marker_recovers_from_torn_clear_record(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-native-file-op-marker-record.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    native_file_op_checkpoint_record marker_record = {0};
    int saw_nonempty_record = 0;
    uint64_t set_generation;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U);
    assert(mylite_close(db) == MYLITE_OK);

    assert(concurrency_wal_is_checkpointed(database_path));
    write_concurrency_checkpoint_lsns(database_path, 0U, 0U);
    write_concurrency_native_file_op_checkpoint_needed(database_path, 1);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(read_concurrency_native_file_op_checkpoint_records(
        database_path,
        &marker_record,
        &saw_nonempty_record
    ));
    assert(saw_nonempty_record);
    assert(marker_record.needed);
    set_generation = marker_record.generation;

    write_concurrency_native_file_op_checkpoint_needed(database_path, 0);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(read_concurrency_native_file_op_checkpoint_records(
        database_path,
        &marker_record,
        &saw_nonempty_record
    ));
    assert(saw_nonempty_record);
    assert(!marker_record.needed);
    assert(marker_record.generation > set_generation);

    corrupt_concurrency_native_file_op_latest_record(database_path);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(concurrency_wal_is_checkpointed(database_path));
    assert(read_concurrency_native_file_op_checkpoint_records(
        database_path,
        &marker_record,
        &saw_nonempty_record
    ));
    assert(saw_nonempty_record);
    assert(!marker_record.needed);
    assert(marker_record.generation > set_generation);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U);
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_native_file_op_marker_drains_after_real_sql_ddl(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-native-file-op-marker-sql.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t peer_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_native_file_op_marker_sql ("
        "id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_native_file_op_marker_sql (value) VALUES (10)");
    assert(query_unsigned(db, "SELECT MAX(id) FROM app.ownerless_native_file_op_marker_sql") == 1U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));

    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);
    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "ALTER TABLE app.ownerless_native_file_op_marker_sql AUTO_INCREMENT = 100");
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(query_unsigned(db, "SELECT MAX(id) FROM app.ownerless_native_file_op_marker_sql") == 1U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    signal_pipe(release_pipe[1]);
    wait_for_child(peer_child);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(concurrency_wal_is_checkpointed(database_path));

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_native_file_op_marker_sql") == 1U
    );
    assert(mylite_close(db) == MYLITE_OK);

    db = open_database(paths, MYLITE_OPEN_READWRITE);
    exec_ok(db, "INSERT INTO app.ownerless_native_file_op_marker_sql (value) VALUES (20)");
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_native_file_op_marker_sql "
            "WHERE id = 100 AND value = 20"
        ) == 1U
    );
    assert(
        query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_native_file_op_marker_sql") == 101U
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_native_file_op_marker_drains_after_checkpointed_dml(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dml-file-op-marker.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_dml_file_op_marker ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "payload VARBINARY(256) NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_dml_file_op_marker VALUES "
        "(1, 10, REPEAT('a', 256))"
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dml_file_op_marker") == 10U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(!read_concurrency_native_dml_file_op_checkpoint_needed(database_path));
    assert(concurrency_wal_is_checkpointed(database_path));

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(mylite_ownerless_innodb_make_checkpoint() == MYLITE_TEST_OWNERLESS_INNODB_LOCK_OK);
    (void)mylite_ownerless_innodb_take_file_op_redo();
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(!read_concurrency_native_dml_file_op_checkpoint_needed(database_path));

    exec_ok(
        db,
        "UPDATE app.ownerless_dml_file_op_marker "
        "SET value = 11, payload = REPEAT('b', 256) "
        "WHERE id = 1"
    );
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(read_concurrency_native_dml_file_op_checkpoint_needed(database_path));
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dml_file_op_marker") == 11U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert(!read_concurrency_native_dml_file_op_checkpoint_needed(database_path));
    assert(concurrency_wal_is_checkpointed(database_path));

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dml_file_op_marker") == 11U);
    assert(
        query_unsigned(
            db,
            "SELECT SUM(ASCII(SUBSTRING(payload, 1, 1))) "
            "FROM app.ownerless_dml_file_op_marker"
        ) == (unsigned)'b'
    );
    assert(mylite_close(db) == MYLITE_OK);

    db = open_database(paths, MYLITE_OPEN_READWRITE);
    exec_ok(
        db,
        "UPDATE app.ownerless_dml_file_op_marker "
        "SET value = 12 "
        "WHERE id = 1"
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dml_file_op_marker") == 12U);
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

