static void test_ownerless_active_reader_pressure_reclaims_after_release(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-active-reader-pressure.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t reader_child;
    const unsigned rounds =
        ownerless_unsigned_env("MYLITE_OWNERLESS_ACTIVE_READER_PRESSURE_ROUNDS", 8U, 500U);
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(concurrency_wal_is_checkpointed(database_path));
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    reader_child = fork();
    assert(reader_child >= 0);
    if (reader_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_repeatable_read_snapshot_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    for (unsigned round = 0U; round < rounds; ++round) {
        const unsigned expected_sum = 31U + round;

        db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
        exec_ok(db, "UPDATE app.ownerless_sql SET value = value + 1 WHERE id = 1");
        {
            const unsigned long long actual_sum =
                query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql");
            if (actual_sum != expected_sum) {
                fprintf(
                    stderr,
                    "active reader pressure sum mismatch: round=%u expected=%u actual=%llu "
                    "visible_lsn=%llu\n",
                    round,
                    expected_sum,
                    actual_sum,
                    (unsigned long long)read_concurrency_redo_visible_lsn(database_path)
                );
            }
            assert(actual_sum == expected_sum);
        }
        assert(mylite_close(db) == MYLITE_OK);
        assert(!concurrency_wal_is_checkpointed(database_path));
        assert(count_concurrency_wal_records_at_or_before(database_path, UINT64_MAX) > 0U);
    }

    signal_pipe(release_pipe[1]);
    wait_for_child(reader_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U + rounds);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U + rounds);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_active_reader_pressure_limit_blocks_writes(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-active-reader-pressure-limit.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t reader_child;
    mylite_db *db;
    mylite_stmt *insert_stmt;
    mylite_stmt *update_stmt;
    const char *tail;
    off_t retained_wal_size;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(concurrency_wal_is_checkpointed(database_path));
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    reader_child = fork();
    assert(reader_child >= 0);
    if (reader_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_repeatable_read_snapshot_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "UPDATE app.ownerless_sql SET value = value + 1 WHERE id = 1");
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(!concurrency_wal_is_checkpointed(database_path));
    retained_wal_size = concurrency_wal_size(database_path);
    assert(retained_wal_size > 0);

    db = open_database_with_page_log_limit(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        (unsigned long long)retained_wal_size
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);
    expect_exec_busy(
        db,
        "UPDATE app.ownerless_sql SET value = value + 1 WHERE id = 2",
        "pressure limit"
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);

    update_stmt = NULL;
    tail = NULL;
    assert(
        mylite_prepare(
            db,
            "UPDATE app.ownerless_sql SET value = value + 1 WHERE id = 2",
            MYLITE_NUL_TERMINATED,
            &update_stmt,
            &tail
        ) == MYLITE_OK
    );
    assert(update_stmt != NULL);
    assert(tail != NULL && *tail == '\0');
    assert(mylite_step(update_stmt) == MYLITE_BUSY);
    assert(mylite_errcode(db) == MYLITE_BUSY);
    assert(mylite_mariadb_errno(db) == 0U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);

    insert_stmt = NULL;
    tail = NULL;
    assert(
        mylite_prepare(
            db,
            "INSERT INTO app.ownerless_sql SELECT 3, 30",
            MYLITE_NUL_TERMINATED,
            &insert_stmt,
            &tail
        ) == MYLITE_OK
    );
    assert(insert_stmt != NULL);
    assert(tail != NULL && *tail == '\0');
    assert(mylite_step(insert_stmt) == MYLITE_BUSY);
    assert(mylite_errcode(db) == MYLITE_BUSY);
    assert(mylite_mariadb_errno(db) == 0U);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 2U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);

    signal_pipe(release_pipe[1]);
    wait_for_child(reader_child);

    assert(mylite_step(update_stmt) == MYLITE_DONE);
    assert(mylite_finalize(update_stmt) == MYLITE_OK);
    assert(mylite_step(insert_stmt) == MYLITE_DONE);
    assert(mylite_finalize(insert_stmt) == MYLITE_OK);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 3U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 62U);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 3U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 62U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void create_ownerless_pressure_compressed_key_block_table(
    mylite_db *db,
    const char *table_name
) {
    char sql[512];

    assert(
        snprintf(
            sql,
            sizeof(sql),
            "CREATE TABLE app.%s ("
            "id INT NOT NULL PRIMARY KEY, "
            "value INT NOT NULL, "
            "payload LONGBLOB NOT NULL"
            ") ENGINE=InnoDB ROW_FORMAT=DYNAMIC",
            table_name
        ) > 0
    );
    exec_ok(db, sql);
    insert_ownerless_compressed_blob_key_block_row(db, table_name, 1U, (unsigned char)'a');
    insert_ownerless_compressed_blob_key_block_row(db, table_name, 2U, (unsigned char)'a');
}

