static void test_ownerless_compressed_blob_key_block_matrix_reclaims_after_release(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-compressed-blob-key-block-matrix.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    const unsigned rows = MYLITE_TEST_COMPRESSED_BLOB_KEY_BLOCK_MATRIX_ROWS;
    const unsigned total_rows =
        rows * (unsigned)(sizeof(ownerless_compressed_blob_key_block_cases) /
                          sizeof(ownerless_compressed_blob_key_block_cases[0]));
    const unsigned long long expected_payload_bytes =
        (unsigned long long)total_rows * MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES;
    unsigned long long expected_first_byte_sum = 0U;
    unsigned updates = 0U;
    int ready_pipe[2];
    int release_pipe[2];
    pid_t reader_child;
    mylite_db *db;
    char sql[256];

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    for (size_t i = 0; i < sizeof(ownerless_compressed_blob_key_block_cases) /
                               sizeof(ownerless_compressed_blob_key_block_cases[0]);
         ++i) {
        const ownerless_compressed_blob_key_block_case *test_case =
            &ownerless_compressed_blob_key_block_cases[i];

        assert(
            snprintf(
                sql,
                sizeof(sql),
                "CREATE TABLE app.%s ("
                "id INT NOT NULL PRIMARY KEY, "
                "value INT NOT NULL, "
                "payload LONGBLOB NOT NULL"
                ") ENGINE=InnoDB ROW_FORMAT=COMPRESSED KEY_BLOCK_SIZE=%u",
                test_case->table_name,
                test_case->key_block_size
            ) > 0
        );
        exec_ok(db, sql);
        for (unsigned row = 1U; row <= rows; ++row) {
            insert_ownerless_compressed_blob_key_block_row(
                db,
                test_case->table_name,
                row,
                (unsigned char)'a'
            );
        }
    }
    assert(query_ownerless_compressed_blob_key_block_matrix_sum(db, "COUNT(*)") == total_rows);
    assert(query_ownerless_compressed_blob_key_block_matrix_sum(db, "SUM(value)") == total_rows);
    assert(
        query_ownerless_compressed_blob_key_block_matrix_sum(db, "SUM(LENGTH(payload))") ==
        expected_payload_bytes
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));
    assert_ownerless_zblob_pages(database_path);

    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    reader_child = fork();
    assert(reader_child >= 0);
    if (reader_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_compressed_blob_key_block_matrix_snapshot_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    for (size_t i = 0; i < sizeof(ownerless_compressed_blob_key_block_cases) /
                               sizeof(ownerless_compressed_blob_key_block_cases[0]);
         ++i) {
        const ownerless_compressed_blob_key_block_case *test_case =
            &ownerless_compressed_blob_key_block_cases[i];

        for (unsigned row = 1U; row <= rows; ++row) {
            const unsigned char payload_byte = (unsigned char)('b' + updates);

            ++updates;
            expected_first_byte_sum += (unsigned long long)payload_byte;
            db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
            update_ownerless_compressed_blob_key_block_row(
                db,
                test_case->table_name,
                row,
                payload_byte
            );
            assert(
                query_ownerless_compressed_blob_key_block_matrix_sum(db, "SUM(value)") ==
                total_rows + updates
            );
            assert(
                query_ownerless_compressed_blob_key_block_matrix_sum(db, "SUM(LENGTH(payload))") ==
                expected_payload_bytes
            );
            assert(mylite_close(db) == MYLITE_OK);
            assert(!concurrency_wal_is_checkpointed(database_path));
            assert(count_concurrency_wal_records_at_or_before(database_path, UINT64_MAX) > 0U);
        }
    }

    signal_pipe(release_pipe[1]);
    wait_for_child(reader_child);

    assert_ownerless_compressed_blob_key_block_matrix_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        expected_first_byte_sum
    );
    assert_ownerless_compressed_blob_key_block_matrix_state(
        paths,
        MYLITE_OPEN_READWRITE,
        expected_first_byte_sum
    );
    remove_concurrency_shm(database_path);
    assert_ownerless_compressed_blob_key_block_matrix_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        expected_first_byte_sum
    );
    assert_ownerless_compressed_blob_key_block_matrix_state(
        paths,
        MYLITE_OPEN_READWRITE,
        expected_first_byte_sum
    );

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_no_live_pressure_reclaim_advances_visible_lsn(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-no-live-pressure-reclaim.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int ready_pipe[2];
    int release_pipe[2];
    pid_t reader_child;
    mylite_db *db;
    uint64_t latest_lsn;
    uint64_t visible_lsn;
    uint64_t lowered_visible_lsn;
    uint64_t checkpoint_visible_after;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(concurrency_wal_is_checkpointed(database_path));
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    reader_child = fork();
    assert(reader_child >= 0);
    if (reader_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_repeatable_read_snapshot_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "UPDATE app.ownerless_sql SET value = value + 1 WHERE id = 1");
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(!concurrency_wal_is_checkpointed(database_path));

    latest_lsn = read_concurrency_checkpoint_latest_lsn(database_path);
    visible_lsn = read_concurrency_checkpoint_visible_lsn(database_path);
    assert(latest_lsn >= visible_lsn);
    assert(visible_lsn > 1U);
    lowered_visible_lsn = visible_lsn - 1U;
    write_concurrency_checkpoint_visible_lsn(database_path, lowered_visible_lsn);
    assert(read_concurrency_checkpoint_visible_lsn(database_path) == lowered_visible_lsn);

    signal_pipe(release_pipe[1]);
    wait_for_child(reader_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed_eventually(database_path);
    checkpoint_visible_after = read_concurrency_checkpoint_visible_lsn(database_path);
    assert(checkpoint_visible_after >= latest_lsn);
    assert(checkpoint_visible_after > lowered_visible_lsn);

    remove_concurrency_wal(database_path);
    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(
        mylite_ownerless_innodb_checkpoint_covers_lsn(checkpoint_visible_after) ==
        MYLITE_TEST_OWNERLESS_INNODB_LOCK_OK
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 31U);
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_dropped_tablespace_replay_skips_missing_space(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dropped-tablespace-replay.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    char *datadir_path;
    char *app_path;
    char *frm_path;
    char *ibd_path;
    char insert_sql[192];
    int ready_pipe[2];
    int release_pipe[2];
    pid_t reader_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(concurrency_wal_is_checkpointed(database_path));

    datadir_path = path_join(database_path, "datadir");
    app_path = path_join(datadir_path, "app");
    frm_path = path_join(app_path, "ownerless_dropped_replay.frm");
    ibd_path = path_join(app_path, "ownerless_dropped_replay.ibd");

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_dropped_replay ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "payload VARBINARY(4000) NOT NULL"
        ") ENGINE=InnoDB"
    );
    for (unsigned id = 1U; id <= 12U; ++id) {
        assert(
            snprintf(
                insert_sql,
                sizeof(insert_sql),
                "INSERT INTO app.ownerless_dropped_replay VALUES "
                "(%u, %u, REPEAT('a', 4000))",
                id,
                id * 10U
            ) > 0
        );
        exec_ok(db, insert_sql);
    }
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dropped_replay") == 780U);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);
    assert(concurrency_wal_is_checkpointed(database_path));

    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);
    reader_child = fork();
    assert(reader_child >= 0);
    if (reader_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        hold_repeatable_read_snapshot_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "UPDATE app.ownerless_dropped_replay "
        "SET value = value + 1, payload = REPEAT('b', 4000)"
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_dropped_replay") == 792U);
    exec_ok(db, "DROP TABLE app.ownerless_dropped_replay");
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_dropped_replay'"
        ) == 0U
    );
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);
    assert(!concurrency_wal_is_checkpointed(database_path));
    assert(count_concurrency_wal_records_at_or_before(database_path, UINT64_MAX) > 0U);

    assert(kill(reader_child, SIGKILL) == 0);
    wait_for_signaled_child(reader_child, SIGKILL);
    assert(close(release_pipe[1]) == 0);

    assert_ownerless_dropped_tablespace_replay_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_dropped_tablespace_replay_state(paths, MYLITE_OPEN_READWRITE, database_path);
    remove_concurrency_shm(database_path);
    assert_ownerless_dropped_tablespace_replay_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_dropped_tablespace_replay_state(paths, MYLITE_OPEN_READWRITE, database_path);

    free(ibd_path);
    free(frm_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

