static void test_ownerless_ddl_refreshes_peer_dictionary(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-ddl-refresh.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    int ddl_ready_pipe[2];
    int ddl_release_pipe[2];
    pid_t ddl_child;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(ddl_ready_pipe) == 0);
    assert(pipe(ddl_release_pipe) == 0);

    ddl_child = fork();
    assert(ddl_child >= 0);
    if (ddl_child == 0) {
        close(ddl_ready_pipe[0]);
        close(ddl_release_pipe[1]);
        run_ownerless_ddl_sequence(
            paths,
            (child_pipes){
                .ready_write_fd = ddl_ready_pipe[1],
                .release_read_fd = ddl_release_pipe[0],
            }
        );
    }

    close(ddl_ready_pipe[1]);
    close(ddl_release_pipe[0]);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 2U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(query_unsigned(db, "SELECT SUM(note) FROM app.ownerless_sql") == 14U);
    exec_ok(db, "UPDATE app.ownerless_sql SET note = note + 1 WHERE id = 1");
    assert(query_unsigned(db, "SELECT SUM(note) FROM app.ownerless_sql") == 15U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_created") == 100U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_renamed") == 100U);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' AND table_name = 'ownerless_created'"
        ) == 0U
    );

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_renamed") == 0U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' AND table_name = 'ownerless_renamed'"
        ) == 0U
    );
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_renamed ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_renamed VALUES (3, 300)");
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_renamed") == 300U);
    close(ddl_ready_pipe[0]);
    close(ddl_release_pipe[1]);
    wait_for_child(ddl_child);
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_table_idempotent_ddl_refreshes_peer_dictionary(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-table-idempotent-ddl.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    int ddl_ready_pipe[2];
    int ddl_release_pipe[2];
    pid_t ddl_child;
    char *datadir_path;
    char *app_path;
    char *frm_path;
    char *ibd_path;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(ddl_ready_pipe) == 0);
    assert(pipe(ddl_release_pipe) == 0);

    ddl_child = fork();
    assert(ddl_child >= 0);
    if (ddl_child == 0) {
        close(ddl_ready_pipe[0]);
        close(ddl_release_pipe[1]);
        run_ownerless_table_idempotent_ddl_sequence(
            paths,
            (child_pipes){
                .ready_write_fd = ddl_ready_pipe[1],
                .release_read_fd = ddl_release_pipe[0],
            }
        );
    }

    datadir_path = path_join(database_path, "datadir");
    app_path = path_join(datadir_path, "app");
    frm_path = path_join(app_path, "ownerless_table_idempotent.frm");
    ibd_path = path_join(app_path, "ownerless_table_idempotent.ibd");

    close(ddl_ready_pipe[1]);
    close(ddl_release_pipe[0]);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 2U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 10U);
    expect_exec_mariadb_error(
        db,
        "CREATE TABLE app.ownerless_table_idempotent ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note INT NOT NULL"
        ") ENGINE=InnoDB",
        MYLITE_TEST_TABLE_EXISTS_ERRNO
    );
    exec_ok(db, "INSERT INTO app.ownerless_table_idempotent VALUES (2, 20)");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent") == 2U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 30U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent' "
            "AND column_name = 'note'"
        ) == 0U
    );
    exec_ok(db, "INSERT INTO app.ownerless_table_idempotent VALUES (3, 30)");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent") == 3U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 60U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent' "
            "AND column_name = 'note'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent") == 1U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 100U);
    exec_ok(
        db,
        "INSERT INTO app.ownerless_table_idempotent (id, value, note) "
        "VALUES (11, 110, 'peer')"
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent") == 2U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 210U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent") == 2U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 210U);

    signal_pipe_message(ddl_release_pipe[1]);
    wait_for_pipe_message(ddl_ready_pipe[0]);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent'"
        ) == 0U
    );
    assert(
        exec_status(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent", NULL) != MYLITE_OK
    );
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));

    close(ddl_ready_pipe[0]);
    close(ddl_release_pipe[1]);
    wait_for_child(ddl_child);
    assert(mylite_close(db) == MYLITE_OK);

    assert_ownerless_table_idempotent_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_table_idempotent_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);
    remove_concurrency_shm(database_path);
    assert_ownerless_table_idempotent_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_table_idempotent_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);

    free(ibd_path);
    free(frm_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_large_truncate_refreshes_peer_allocation(void) {
    enum {
        initial_rows = 48U,
        reuse_rows = 12U,
    };

    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-large-truncate-refresh.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    int ready_pipe[2];
    int release_pipe[2];
    pid_t truncator_child;
    char sql[256];

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(ready_pipe) == 0);
    assert(pipe(release_pipe) == 0);

    truncator_child = fork();
    assert(truncator_child >= 0);
    if (truncator_child == 0) {
        close(ready_pipe[0]);
        close(release_pipe[1]);
        truncate_ownerless_large_table_after_signal(
            paths,
            (child_pipes){
                .ready_write_fd = ready_pipe[1],
                .release_read_fd = release_pipe[0],
            }
        );
    }

    close(ready_pipe[1]);
    close(release_pipe[0]);
    wait_for_pipe(ready_pipe[0]);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_truncate_bounds ("
        "id INT NOT NULL PRIMARY KEY, "
        "payload VARBINARY(4000) NOT NULL"
        ") ENGINE=InnoDB"
    );
    for (unsigned id = 1U; id <= initial_rows; ++id) {
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "INSERT INTO app.ownerless_truncate_bounds VALUES (%u, REPEAT('x', 4000))",
                id
            ) > 0
        );
        exec_ok(db, sql);
    }
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_truncate_bounds") == initial_rows
    );

    signal_pipe(release_pipe[1]);
    wait_for_child(truncator_child);

    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_truncate_bounds") == 0U);
    for (unsigned id = 1U; id <= reuse_rows; ++id) {
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "INSERT INTO app.ownerless_truncate_bounds VALUES (%u, REPEAT('y', 4000))",
                id
            ) > 0
        );
        exec_ok(db, sql);
    }
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_truncate_bounds") == reuse_rows);
    assert(
        query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_truncate_bounds") ==
        (reuse_rows * (reuse_rows + 1U)) / 2U
    );
    assert(mylite_close(db) == MYLITE_OK);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

