static void test_ownerless_generated_column_blocked_function_policy(void) {
    const struct {
        const char *sql;
    } rejected_create_cases[] = {
        {
            "CREATE TABLE app.ownerless_generated_blocked_aggregate ("
            "id INT NOT NULL PRIMARY KEY, "
            "base_value INT NOT NULL, "
            "aggregate_value INT GENERATED ALWAYS AS (SUM(base_value)) VIRTUAL"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_subquery ("
            "id INT NOT NULL PRIMARY KEY, "
            "base_value INT NOT NULL, "
            "subquery_value INT GENERATED ALWAYS AS ((SELECT 1)) VIRTUAL"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_stored_now ("
            "id INT NOT NULL PRIMARY KEY, "
            "created_at DATETIME GENERATED ALWAYS AS (CURRENT_TIMESTAMP()) STORED"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_stored_database ("
            "id INT NOT NULL PRIMARY KEY, "
            "database_value VARCHAR(64) GENERATED ALWAYS AS (DATABASE()) STORED"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_stored_uuid ("
            "id INT NOT NULL PRIMARY KEY, "
            "uuid_value VARCHAR(64) GENERATED ALWAYS AS (UUID()) STORED"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_aes_encrypt ("
            "id INT NOT NULL PRIMARY KEY, "
            "crypto_value VARBINARY(255) GENERATED ALWAYS AS "
            "(AES_ENCRYPT('abc', 'bcd')) STORED"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_found_rows ("
            "id INT NOT NULL PRIMARY KEY, "
            "found_rows_value BIGINT GENERATED ALWAYS AS (FOUND_ROWS()) VIRTUAL"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_last_insert_id ("
            "id INT NOT NULL PRIMARY KEY, "
            "last_id BIGINT GENERATED ALWAYS AS (LAST_INSERT_ID()) VIRTUAL"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_row_count ("
            "id INT NOT NULL PRIMARY KEY, "
            "row_count_value INT GENERATED ALWAYS AS (ROW_COUNT()) VIRTUAL"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_user ("
            "id INT NOT NULL PRIMARY KEY, "
            "user_value VARCHAR(128) GENERATED ALWAYS AS (USER()) STORED"
            ") ENGINE=InnoDB",
        },
        {
            "CREATE TABLE app.ownerless_generated_blocked_version ("
            "id INT NOT NULL PRIMARY KEY, "
            "version_value VARCHAR(128) GENERATED ALWAYS AS (VERSION()) STORED"
            ") ENGINE=InnoDB",
        },
    };

    const struct {
        const char *sql;
    } failed_alter_cases[] = {
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "ADD COLUMN now_value DATETIME GENERATED ALWAYS AS (NOW()) STORED",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "ADD COLUMN aggregate_value INT GENERATED ALWAYS AS (SUM(base_value)) VIRTUAL",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "MODIFY COLUMN stored_label VARCHAR(64) GENERATED ALWAYS AS (UUID()) STORED",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "MODIFY COLUMN stored_value INT GENERATED ALWAYS AS ((SELECT 1)) STORED",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "ADD COLUMN row_count_value INT GENERATED ALWAYS AS (ROW_COUNT()) VIRTUAL",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "ADD COLUMN user_value VARCHAR(128) GENERATED ALWAYS AS (USER()) STORED",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_alter "
            "MODIFY COLUMN stored_label VARCHAR(128) GENERATED ALWAYS AS (VERSION()) STORED",
        },
    };

    const struct {
        const char *sql;
    } failed_index_cases[] = {
        {
            "CREATE INDEX ownerless_generated_blocked_rand_idx "
            "ON app.ownerless_generated_blocked_virtual_index (rand_value)",
        },
        {
            "ALTER TABLE app.ownerless_generated_blocked_virtual_index "
            "ADD INDEX ownerless_generated_blocked_connection_idx (connection_value)",
        },
        {
            "CREATE INDEX ownerless_generated_blocked_database_idx "
            "ON app.ownerless_generated_blocked_virtual_index (database_value)",
        },
    };

    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path =
        path_join(root, "ownerless-generated-column-blocked-function-policy.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);

    for (size_t index = 0U;
         index < sizeof(rejected_create_cases) / sizeof(rejected_create_cases[0]);
         ++index) {
        expect_exec_mariadb_error(
            db,
            rejected_create_cases[index].sql,
            MYLITE_TEST_GENERATED_COLUMN_FUNCTION_ERRNO
        );
    }
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name LIKE 'ownerless_generated_blocked_%' "
            "AND table_name NOT IN ("
            "'ownerless_generated_blocked_alter', "
            "'ownerless_generated_blocked_virtual_index')"
        ) == 0U
    );

    exec_ok(
        db,
        "CREATE TABLE app.ownerless_generated_blocked_alter ("
        "id INT NOT NULL PRIMARY KEY, "
        "base_value INT NOT NULL, "
        "stored_value INT GENERATED ALWAYS AS (base_value + 1) STORED, "
        "stored_label VARCHAR(32) GENERATED ALWAYS AS (CONCAT('v', base_value)) STORED"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_generated_blocked_alter "
        "(id, base_value) VALUES (1, 10), (2, 20)"
    );
    for (size_t index = 0U; index < sizeof(failed_alter_cases) / sizeof(failed_alter_cases[0]);
         ++index) {
        expect_exec_mariadb_error(
            db,
            failed_alter_cases[index].sql,
            MYLITE_TEST_GENERATED_COLUMN_FUNCTION_ERRNO
        );
    }
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_generated_blocked_alter' "
            "AND column_name IN ("
            "'now_value', "
            "'aggregate_value', "
            "'row_count_value', "
            "'user_value')"
        ) == 0U
    );
    assert(
        query_unsigned(db, "SELECT SUM(stored_value) FROM app.ownerless_generated_blocked_alter") ==
        32U
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_generated_blocked_alter "
        "(id, base_value) VALUES (3, 30)"
    );

    exec_ok(
        db,
        "CREATE TABLE app.ownerless_generated_blocked_virtual_index ("
        "id INT NOT NULL PRIMARY KEY, "
        "base_value INT NOT NULL, "
        "rand_value DOUBLE GENERATED ALWAYS AS (RAND()) VIRTUAL, "
        "connection_value BIGINT GENERATED ALWAYS AS (CONNECTION_ID()) VIRTUAL, "
        "database_value VARCHAR(64) GENERATED ALWAYS AS (DATABASE()) VIRTUAL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_generated_blocked_virtual_index "
        "(id, base_value) VALUES (1, 10), (2, 20)"
    );
    for (size_t index = 0U; index < sizeof(failed_index_cases) / sizeof(failed_index_cases[0]);
         ++index) {
        expect_exec_mariadb_error(
            db,
            failed_index_cases[index].sql,
            MYLITE_TEST_GENERATED_COLUMN_FUNCTION_ERRNO
        );
    }
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.statistics "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_generated_blocked_virtual_index' "
            "AND index_name IN ("
            "'ownerless_generated_blocked_rand_idx', "
            "'ownerless_generated_blocked_connection_idx', "
            "'ownerless_generated_blocked_database_idx')"
        ) == 0U
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_generated_blocked_virtual_index "
        "(id, base_value) VALUES (3, 30)"
    );

    assert(mylite_close(db) == MYLITE_OK);
    assert_ownerless_generated_column_blocked_function_policy_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_generated_column_blocked_function_policy_state(paths, MYLITE_OPEN_READWRITE);
    remove_concurrency_shm(database_path);
    assert_ownerless_generated_column_blocked_function_policy_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_generated_column_blocked_function_policy_state(paths, MYLITE_OPEN_READWRITE);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_ownerless_charset_convert_ddl_refreshes_peer_dictionary(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-charset-convert-ddl.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    mylite_db *db;
    int charset_ready_pipe[2];
    int charset_release_pipe[2];
    pid_t charset_child;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    assert(pipe(charset_ready_pipe) == 0);
    assert(pipe(charset_release_pipe) == 0);

    charset_child = fork();
    assert(charset_child >= 0);
    if (charset_child == 0) {
        close(charset_ready_pipe[0]);
        close(charset_release_pipe[1]);
        run_ownerless_charset_convert_ddl_sequence(
            paths,
            (child_pipes){
                .ready_write_fd = charset_ready_pipe[1],
                .release_read_fd = charset_release_pipe[0],
            }
        );
    }

    close(charset_ready_pipe[1]);
    close(charset_release_pipe[0]);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 2U);

    signal_pipe_message(charset_release_pipe[1]);
    wait_for_pipe_message(charset_ready_pipe[0]);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_charset_convert_base' "
            "AND column_name = 'name' "
            "AND character_set_name = 'latin1' "
            "AND collation_name = 'latin1_swedish_ci'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_charset_convert_base") == 30U);
    assert(
        query_unsigned(
            db,
            "SELECT SUM(CHAR_LENGTH(name)) FROM app.ownerless_charset_convert_base"
        ) == 9U
    );

    signal_pipe_message(charset_release_pipe[1]);
    wait_for_pipe_message(charset_ready_pipe[0]);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_charset_convert_base' "
            "AND column_name = 'name' "
            "AND character_set_name = 'utf8mb4' "
            "AND collation_name = 'utf8mb4_general_ci'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_charset_convert_base") == 30U);
    exec_ok(db, "INSERT INTO app.ownerless_charset_convert_base VALUES (3, 'gamma', 30)");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_charset_convert_base") == 3U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_charset_convert_base") == 60U);
    assert(
        query_unsigned(
            db,
            "SELECT SUM(CHAR_LENGTH(name)) FROM app.ownerless_charset_convert_base"
        ) == 14U
    );

    close(charset_ready_pipe[0]);
    close(charset_release_pipe[1]);
    wait_for_child(charset_child);
    assert(mylite_close(db) == MYLITE_OK);

    assert_ownerless_charset_convert_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_charset_convert_ddl_state(paths, MYLITE_OPEN_READWRITE);
    remove_concurrency_shm(database_path);
    assert_ownerless_charset_convert_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_charset_convert_ddl_state(paths, MYLITE_OPEN_READWRITE);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

