    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_sql") == 2U);

    signal_pipe_message(view_release_pipe[1]);
    wait_for_pipe_message(view_ready_pipe[0]);
    assert(path_exists(view_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_view_column_list' "
            "AND column_name = 'view_id' "
            "AND ordinal_position = 1"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_view_column_list' "
            "AND column_name = 'view_value' "
            "AND ordinal_position = 2"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_view_column_list") == 2U);
    assert(query_unsigned(db, "SELECT SUM(view_value) FROM app.ownerless_view_column_list") == 30U);
    exec_ok(db, "INSERT INTO app.ownerless_view_column_base VALUES (3, 30, 'peer-added')");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_view_column_list") == 3U);
    assert(query_unsigned(db, "SELECT SUM(view_value) FROM app.ownerless_view_column_list") == 60U);

