static void test_crashed_multi_rename_dictionary_ddl_recovers_swapped_tables(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-multi-rename-crash.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    char *datadir_path;
    char *app_path;
    char *left_frm_path;
    char *left_ibd_path;
    char *right_frm_path;
    char *right_ibd_path;
    char *tmp_frm_path;
    char *tmp_ibd_path;
    ownerless_live_peer_guard live_peer;
    unsigned long long left_space_before;
    unsigned long long right_space_before;
    unsigned long long left_space_after;
    unsigned long long right_space_after;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    datadir_path = path_join(database_path, "datadir");
    app_path = path_join(datadir_path, "app");
    left_frm_path = path_join(app_path, "ownerless_multi_rename_crash_left.frm");
    left_ibd_path = path_join(app_path, "ownerless_multi_rename_crash_left.ibd");
    right_frm_path = path_join(app_path, "ownerless_multi_rename_crash_right.frm");
    right_ibd_path = path_join(app_path, "ownerless_multi_rename_crash_right.ibd");
    tmp_frm_path = path_join(app_path, "ownerless_multi_rename_crash_tmp.frm");
    tmp_ibd_path = path_join(app_path, "ownerless_multi_rename_crash_tmp.ibd");

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_multi_rename_crash_left ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note VARCHAR(16) NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_multi_rename_crash_right ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note VARCHAR(16) NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_multi_rename_crash_left VALUES "
        "(1, 10, 'left'), (2, 20, 'left')"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_multi_rename_crash_right VALUES "
        "(10, 100, 'right'), (20, 200, 'right')"
    );
    assert(path_exists(left_frm_path));
    assert(path_exists(left_ibd_path));
    assert(path_exists(right_frm_path));
    assert(path_exists(right_ibd_path));
    assert(!path_exists(tmp_frm_path));
    assert(!path_exists(tmp_ibd_path));
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_left") == 30U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_right") == 300U
    );
    left_space_before = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_multi_rename_crash_left'"
    );
    right_space_before = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_multi_rename_crash_right'"
    );
    assert(left_space_before > 0U);
    assert(right_space_before > 0U);
    assert(left_space_before != right_space_before);
    assert(mylite_close(db) == MYLITE_OK);

    live_peer = crash_ownerless_dictionary_writer_with_held_live_peer(
        paths,
        rename_multi_table_until_dictionary_finish_fault
    );
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_multi_rename_crash_left'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_multi_rename_crash_right'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_multi_rename_crash_tmp'"
        ) == 0U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.INNODB_SYS_TABLES "
            "WHERE NAME = 'app/ownerless_multi_rename_crash_tmp'"
        ) == 0U
    );
    left_space_after = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_multi_rename_crash_left'"
    );
    right_space_after = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_multi_rename_crash_right'"
    );
    assert(left_space_after == right_space_before);
    assert(right_space_after == left_space_before);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_multi_rename_crash_left") == 2U);
    assert(query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_multi_rename_crash_left") == 30U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_left") == 300U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_multi_rename_crash_left WHERE note = 'right'"
        ) == 2U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_multi_rename_crash_right") == 2U);
    assert(query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_multi_rename_crash_right") == 3U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_right") == 30U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_multi_rename_crash_right WHERE note = 'left'"
        ) == 2U
    );
    exec_ok(db, "INSERT INTO app.ownerless_multi_rename_crash_left VALUES (30, 300, 'peer-left')");
    exec_ok(db, "INSERT INTO app.ownerless_multi_rename_crash_right VALUES (3, 30, 'peer-right')");
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_left") == 600U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_multi_rename_crash_right") == 60U
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    release_ownerless_live_peer(&live_peer);

    assert_ownerless_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path,
        right_space_before,
        left_space_before
    );
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert_ownerless_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE,
        database_path,
        right_space_before,
        left_space_before
    );
    remove_concurrency_shm(database_path);
    assert_ownerless_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path,
        right_space_before,
        left_space_before
    );
    assert_ownerless_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE,
        database_path,
        right_space_before,
        left_space_before
    );

    free(tmp_ibd_path);
    free(tmp_frm_path);
    free(right_ibd_path);
    free(right_frm_path);
    free(left_ibd_path);
    free(left_frm_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_crashed_cross_schema_multi_rename_dictionary_ddl_recovers_swapped_tables(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path =
        path_join(root, "ownerless-dictionary-cross-schema-multi-rename-crash.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    char *datadir_path;
    char *app_path;
    char *schema_path;
    char *left_frm_path;
    char *left_ibd_path;
    char *right_frm_path;
    char *right_ibd_path;
    char *tmp_frm_path;
    char *tmp_ibd_path;
    ownerless_live_peer_guard live_peer;
    unsigned long long left_space_before;
    unsigned long long right_space_before;
    unsigned long long left_space_after;
    unsigned long long right_space_after;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    datadir_path = path_join(database_path, "datadir");
    app_path = path_join(datadir_path, "app");
    schema_path = path_join(datadir_path, "ownerless_cross_multi_rename_crash_archive");
    left_frm_path = path_join(app_path, "ownerless_cross_multi_rename_crash_left.frm");
    left_ibd_path = path_join(app_path, "ownerless_cross_multi_rename_crash_left.ibd");
    right_frm_path = path_join(schema_path, "ownerless_cross_multi_rename_crash_right.frm");
    right_ibd_path = path_join(schema_path, "ownerless_cross_multi_rename_crash_right.ibd");
    tmp_frm_path = path_join(schema_path, "ownerless_cross_multi_rename_crash_tmp.frm");
    tmp_ibd_path = path_join(schema_path, "ownerless_cross_multi_rename_crash_tmp.ibd");

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "CREATE DATABASE ownerless_cross_multi_rename_crash_archive");
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_cross_multi_rename_crash_left ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note VARCHAR(16) NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "CREATE TABLE ownerless_cross_multi_rename_crash_archive."
        "ownerless_cross_multi_rename_crash_right ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note VARCHAR(16) NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_cross_multi_rename_crash_left VALUES "
        "(1, 10, 'left'), (2, 20, 'left')"
    );
    exec_ok(
        db,
        "INSERT INTO ownerless_cross_multi_rename_crash_archive."
        "ownerless_cross_multi_rename_crash_right VALUES "
        "(10, 100, 'right'), (20, 200, 'right')"
    );
    assert(path_exists(schema_path));
    assert(path_exists(left_frm_path));
    assert(path_exists(left_ibd_path));
    assert(path_exists(right_frm_path));
    assert(path_exists(right_ibd_path));
    assert(!path_exists(tmp_frm_path));
    assert(!path_exists(tmp_ibd_path));
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_cross_multi_rename_crash_left") ==
        30U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(value) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right"
        ) == 300U
    );
    left_space_before = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_cross_multi_rename_crash_left'"
    );
    right_space_before = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'ownerless_cross_multi_rename_crash_archive/"
        "ownerless_cross_multi_rename_crash_right'"
    );
    assert(left_space_before > 0U);
    assert(right_space_before > 0U);
    assert(left_space_before != right_space_before);
    assert(mylite_close(db) == MYLITE_OK);

    live_peer = crash_ownerless_dictionary_writer_with_held_live_peer(
        paths,
        rename_cross_schema_multi_table_until_dictionary_finish_fault
    );
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.schemata "
            "WHERE schema_name = 'ownerless_cross_multi_rename_crash_archive'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_cross_multi_rename_crash_left'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'ownerless_cross_multi_rename_crash_archive' "
            "AND table_name = 'ownerless_cross_multi_rename_crash_right'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'ownerless_cross_multi_rename_crash_archive' "
            "AND table_name = 'ownerless_cross_multi_rename_crash_tmp'"
        ) == 0U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.INNODB_SYS_TABLES "
            "WHERE NAME = 'ownerless_cross_multi_rename_crash_archive/"
            "ownerless_cross_multi_rename_crash_tmp'"
        ) == 0U
    );
    left_space_after = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'app/ownerless_cross_multi_rename_crash_left'"
    );
    right_space_after = query_unsigned(
        db,
        "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
        "WHERE NAME = 'ownerless_cross_multi_rename_crash_archive/"
        "ownerless_cross_multi_rename_crash_right'"
    );
    assert(left_space_after == right_space_before);
    assert(right_space_after == left_space_before);
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_cross_multi_rename_crash_left") == 2U
    );
    assert(
        query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_cross_multi_rename_crash_left") == 30U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_cross_multi_rename_crash_left") ==
        300U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_cross_multi_rename_crash_left "
            "WHERE note = 'right'"
        ) == 2U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right"
        ) == 2U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(id) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right"
        ) == 3U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(value) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right"
        ) == 30U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right WHERE note = 'left'"
        ) == 2U
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_cross_multi_rename_crash_left VALUES "
        "(30, 300, 'peer-left')"
    );
    exec_ok(
        db,
        "INSERT INTO ownerless_cross_multi_rename_crash_archive."
        "ownerless_cross_multi_rename_crash_right VALUES "
        "(3, 30, 'peer-right')"
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_cross_multi_rename_crash_left") ==
        600U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(value) FROM ownerless_cross_multi_rename_crash_archive."
            "ownerless_cross_multi_rename_crash_right"
        ) == 60U
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    release_ownerless_live_peer(&live_peer);

    assert_ownerless_cross_schema_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path,
        right_space_before,
        left_space_before
    );
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    assert_ownerless_cross_schema_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE,
        database_path,
        right_space_before,
        left_space_before
    );
    remove_concurrency_shm(database_path);
    assert_ownerless_cross_schema_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path,
        right_space_before,
        left_space_before
    );
    assert_ownerless_cross_schema_multi_rename_crash_state(
        paths,
        MYLITE_OPEN_READWRITE,
        database_path,
        right_space_before,
        left_space_before
    );

    free(tmp_ibd_path);
    free(tmp_frm_path);
    free(right_ibd_path);
    free(right_frm_path);
    free(left_ibd_path);
    free(left_frm_path);
    free(schema_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_crashed_secondary_index_dictionary_ddl_recovers_index_metadata(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-secondary-index-crash.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int writer_ready_pipe[2];
    int peer_ready_pipe[2];
    int peer_release_pipe[2];
    pid_t writer_child;
    pid_t peer_child;
    pid_t probe_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_index_crash_base ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_index_crash_base VALUES "
        "(1, 10, 100), (2, 20, 200), (3, 30, 300)"
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.statistics "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_index_crash_base' "
            "AND index_name = 'ownerless_index_crash_value_idx'"
        ) == 0U
    );
    assert(
        exec_status(
            db,
            "SELECT SUM(id) FROM app.ownerless_index_crash_base "
            "FORCE INDEX (ownerless_index_crash_value_idx) "
            "WHERE value >= 20",
            NULL
        ) != MYLITE_OK
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert(pipe(writer_ready_pipe) == 0);
    assert(pipe(peer_ready_pipe) == 0);
    assert(pipe(peer_release_pipe) == 0);

    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        close(writer_ready_pipe[0]);
        close(writer_ready_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = peer_ready_pipe[1],
                .release_read_fd = peer_release_pipe[0],
            }
        );
    }

    close(peer_ready_pipe[1]);
    close(peer_release_pipe[0]);
    wait_for_pipe(peer_ready_pipe[0]);

    writer_child = fork();
    assert(writer_child >= 0);
    if (writer_child == 0) {
        close(writer_ready_pipe[0]);
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        create_secondary_index_until_dictionary_finish_fault(paths, writer_ready_pipe[1]);
    }

    close(writer_ready_pipe[1]);
    wait_for_pipe(writer_ready_pipe[0]);
    assert(kill(writer_child, SIGKILL) == 0);
    wait_for_signaled_child(writer_child, SIGKILL);

    probe_child = fork();
    assert(probe_child >= 0);
    if (probe_child == 0) {
        assert_ownerless_open_returns_busy(paths);
    }
    wait_for_child(probe_child);

    signal_pipe(peer_release_pipe[1]);
    wait_for_child(peer_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.statistics "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_index_crash_base' "
            "AND index_name = 'ownerless_index_crash_value_idx' "
            "AND column_name = 'value'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(id) FROM app.ownerless_index_crash_base "
            "FORCE INDEX (ownerless_index_crash_value_idx) "
            "WHERE value >= 20"
        ) == 5U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_index_crash_base") == 3U);
    assert(query_unsigned(db, "SELECT SUM(note) FROM app.ownerless_index_crash_base") == 600U);
    exec_ok(db, "INSERT INTO app.ownerless_index_crash_base VALUES (4, 40, 400)");
    assert(
        query_unsigned(
            db,
            "SELECT SUM(id) FROM app.ownerless_index_crash_base "
            "FORCE INDEX (ownerless_index_crash_value_idx) "
            "WHERE value >= 20"
        ) == 9U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert_ownerless_secondary_index_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_secondary_index_crash_state(paths, MYLITE_OPEN_READWRITE);
    remove_concurrency_shm(database_path);
    assert_ownerless_secondary_index_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_secondary_index_crash_state(paths, MYLITE_OPEN_READWRITE);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

