static void run_crashed_create_like_dictionary_ddl_recovers_table(int assert_file_op_marker) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-create-like-crash.mylite");
    char *datadir_path = path_join(database_path, "datadir");
    char *app_path = path_join(datadir_path, "app");
    char *copy_frm_path = path_join(app_path, "ownerless_create_like_crash_copy.frm");
    char *copy_ibd_path = path_join(app_path, "ownerless_create_like_crash_copy.ibd");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int writer_ready_pipe[2];
    int peer_ready_pipe[2];
    int peer_release_pipe[2];
    pid_t writer_child;
    pid_t peer_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_create_like_crash_source ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note VARCHAR(16) NOT NULL, "
        "INDEX ownerless_create_like_crash_value_idx (value)"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_create_like_crash_source VALUES "
        "(1, 10, 'alpha'), (2, 20, 'beta')"
    );
    exec_ok(db, "COMMIT");
    assert(!path_exists(copy_frm_path));
    assert(!path_exists(copy_ibd_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_create_like_crash_copy'"
        ) == 0U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert(pipe(writer_ready_pipe) == 0);
    assert(pipe(peer_ready_pipe) == 0);
    assert(pipe(peer_release_pipe) == 0);

    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        close(writer_ready_pipe[0]);
        close(writer_ready_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = peer_ready_pipe[1],
                .release_read_fd = peer_release_pipe[0],
            }
        );
    }

    close(peer_ready_pipe[1]);
    close(peer_release_pipe[0]);
    wait_for_pipe(peer_ready_pipe[0]);

    writer_child = fork();
    assert(writer_child >= 0);
    if (writer_child == 0) {
        close(writer_ready_pipe[0]);
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        create_like_until_dictionary_finish_fault(paths, writer_ready_pipe[1]);
    }

    close(writer_ready_pipe[1]);
    wait_for_pipe(writer_ready_pipe[0]);
    assert(kill(writer_child, SIGKILL) == 0);
    wait_for_signaled_child(writer_child, SIGKILL);
    if (assert_file_op_marker) {
        assert(read_concurrency_native_file_op_checkpoint_needed(database_path));
    }

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(path_exists(copy_frm_path));
    assert(path_exists(copy_ibd_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_create_like_crash_copy' "
            "AND table_type = 'BASE TABLE'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.statistics "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_create_like_crash_copy' "
            "AND index_name = 'ownerless_create_like_crash_value_idx' "
            "AND column_name = 'value'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_create_like_crash_copy") == 0U);
    exec_ok(
        db,
        "INSERT INTO app.ownerless_create_like_crash_copy VALUES "
        "(1, 10, 'copy'), (2, 20, 'copy')"
    );
    exec_ok(db, "COMMIT");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_create_like_crash_copy") == 2U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_create_like_crash_copy") == 30U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(id) FROM app.ownerless_create_like_crash_copy "
            "FORCE INDEX (ownerless_create_like_crash_value_idx) "
            "WHERE value >= 20"
        ) == 2U
    );
    assert(mylite_close(db) == MYLITE_OK);

    if (assert_file_op_marker) {
        assert(read_concurrency_native_file_op_checkpoint_needed(database_path));
    }

    signal_pipe(peer_release_pipe[1]);
    wait_for_child(peer_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_create_like_crash_copy") == 2U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_create_like_crash_copy") == 30U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(id) FROM app.ownerless_create_like_crash_copy "
            "FORCE INDEX (ownerless_create_like_crash_value_idx) "
            "WHERE value >= 20"
        ) == 2U
    );
    assert(mylite_close(db) == MYLITE_OK);

    if (assert_file_op_marker) {
        assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));
    }

    assert_ownerless_create_like_crash_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_create_like_crash_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);
    remove_concurrency_shm(database_path);
    assert_ownerless_create_like_crash_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_create_like_crash_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);

    free(copy_ibd_path);
    free(copy_frm_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

static void test_crashed_create_like_dictionary_ddl_recovers_table(void) {
    run_crashed_create_like_dictionary_ddl_recovers_table(0);
}

static void test_crashed_create_like_dictionary_ddl_marks_file_op_checkpoint(void) {
    run_crashed_create_like_dictionary_ddl_recovers_table(1);
}

