static void test_crashed_trigger_create_dictionary_ddl_recovers_trigger(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-trigger-create-crash.mylite");
    char *datadir_path = path_join(database_path, "datadir");
    char *app_path = path_join(datadir_path, "app");
    char *trg_path = path_join(app_path, "ownerless_trigger_create_crash_base.TRG");
    char *trn_path = path_join(app_path, "ownerless_trigger_create_crash_ai.TRN");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int writer_ready_pipe[2];
    int peer_ready_pipe[2];
    int peer_release_pipe[2];
    pid_t writer_child;
    pid_t peer_child;
    pid_t probe_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_trigger_create_crash_base ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_trigger_create_crash_audit ("
        "base_id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "COMMIT");
    assert(!path_exists(trg_path));
    assert(!path_exists(trn_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.triggers "
            "WHERE trigger_schema = 'app' "
            "AND trigger_name = 'ownerless_trigger_create_crash_ai'"
        ) == 0U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert(pipe(writer_ready_pipe) == 0);
    assert(pipe(peer_ready_pipe) == 0);
    assert(pipe(peer_release_pipe) == 0);

    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        close(writer_ready_pipe[0]);
        close(writer_ready_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = peer_ready_pipe[1],
                .release_read_fd = peer_release_pipe[0],
            }
        );
    }

    close(peer_ready_pipe[1]);
    close(peer_release_pipe[0]);
    wait_for_pipe(peer_ready_pipe[0]);

    writer_child = fork();
    assert(writer_child >= 0);
    if (writer_child == 0) {
        close(writer_ready_pipe[0]);
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        create_trigger_until_dictionary_finish_fault(paths, writer_ready_pipe[1]);
    }

    close(writer_ready_pipe[1]);
    wait_for_pipe(writer_ready_pipe[0]);
    assert(kill(writer_child, SIGKILL) == 0);
    wait_for_signaled_child(writer_child, SIGKILL);

    probe_child = fork();
    assert(probe_child >= 0);
    if (probe_child == 0) {
        assert_ownerless_open_returns_busy(paths);
    }
    wait_for_child(probe_child);

    signal_pipe(peer_release_pipe[1]);
    wait_for_child(peer_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(path_exists(trg_path));
    assert(path_exists(trn_path));
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.triggers "
            "WHERE trigger_schema = 'app' "
            "AND trigger_name = 'ownerless_trigger_create_crash_ai' "
            "AND event_object_table = 'ownerless_trigger_create_crash_base' "
            "AND event_manipulation = 'INSERT' "
            "AND action_timing = 'AFTER'"
        ) == 1U
    );
    assert_show_create_trigger_contains(
        db,
        "SHOW CREATE TRIGGER app.ownerless_trigger_create_crash_ai",
        "ownerless_trigger_create_crash_ai",
        "ownerless_trigger_create_crash_audit"
    );
    exec_ok(db, "INSERT INTO app.ownerless_trigger_create_crash_base VALUES (1, 10)");
    exec_ok(db, "COMMIT");
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_trigger_create_crash_base") == 1U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_trigger_create_crash_base") == 10U
    );
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_trigger_create_crash_audit") == 1U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_trigger_create_crash_audit") == 10U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert_ownerless_trigger_create_crash_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_trigger_create_crash_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);
    remove_concurrency_shm(database_path);
    assert_ownerless_trigger_create_crash_ddl_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW,
        database_path
    );
    assert_ownerless_trigger_create_crash_ddl_state(paths, MYLITE_OPEN_READWRITE, database_path);

    free(trn_path);
    free(trg_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

