static void test_crashed_column_drop_dictionary_ddl_recovers_absent_column(void) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-column-drop-crash.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    int writer_ready_pipe[2];
    int peer_ready_pipe[2];
    int peer_release_pipe[2];
    pid_t writer_child;
    pid_t peer_child;
    pid_t probe_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_column_drop_crash_base ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL, "
        "note INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(
        db,
        "INSERT INTO app.ownerless_column_drop_crash_base VALUES "
        "(1, 10, 100), (2, 20, 200), (3, 30, 300)"
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_column_drop_crash_base' "
            "AND column_name = 'note'"
        ) == 1U
    );
    assert(
        query_unsigned(db, "SELECT SUM(note) FROM app.ownerless_column_drop_crash_base") == 600U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert(pipe(writer_ready_pipe) == 0);
    assert(pipe(peer_ready_pipe) == 0);
    assert(pipe(peer_release_pipe) == 0);

    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        close(writer_ready_pipe[0]);
        close(writer_ready_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = peer_ready_pipe[1],
                .release_read_fd = peer_release_pipe[0],
            }
        );
    }

    close(peer_ready_pipe[1]);
    close(peer_release_pipe[0]);
    wait_for_pipe(peer_ready_pipe[0]);

    writer_child = fork();
    assert(writer_child >= 0);
    if (writer_child == 0) {
        close(writer_ready_pipe[0]);
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        drop_column_until_dictionary_finish_fault(paths, writer_ready_pipe[1]);
    }

    close(writer_ready_pipe[1]);
    wait_for_pipe(writer_ready_pipe[0]);
    assert(kill(writer_child, SIGKILL) == 0);
    wait_for_signaled_child(writer_child, SIGKILL);

    probe_child = fork();
    assert(probe_child >= 0);
    if (probe_child == 0) {
        assert_ownerless_open_returns_busy(paths);
    }
    wait_for_child(probe_child);

    signal_pipe(peer_release_pipe[1]);
    wait_for_child(peer_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_column_drop_crash_base' "
            "AND column_name = 'note'"
        ) == 0U
    );
    assert(
        exec_status(db, "SELECT SUM(note) FROM app.ownerless_column_drop_crash_base", NULL) !=
        MYLITE_OK
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_column_drop_crash_base") == 3U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_column_drop_crash_base") == 60U
    );
    exec_ok(db, "INSERT INTO app.ownerless_column_drop_crash_base (id, value) VALUES (4, 40)");
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_column_drop_crash_base") == 4U);
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_column_drop_crash_base") == 100U
    );
    assert(mylite_close(db) == MYLITE_OK);

    assert_ownerless_column_drop_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_column_drop_crash_state(paths, MYLITE_OPEN_READWRITE);
    remove_concurrency_shm(database_path);
    assert_ownerless_column_drop_crash_state(
        paths,
        MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW
    );
    assert_ownerless_column_drop_crash_state(paths, MYLITE_OPEN_READWRITE);

    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

