static void run_crashed_drop_dictionary_ddl_recovers_absent_table(int assert_file_op_marker) {
    char *root = make_temp_root();
    char *runtime_root = path_join(root, "runtime");
    char *database_path = path_join(root, "ownerless-dictionary-drop-crash.mylite");
    open_database_paths paths = {.database_path = database_path, .runtime_root = runtime_root};
    char *datadir_path;
    char *app_path;
    char *frm_path;
    char *ibd_path;
    int writer_ready_pipe[2];
    int peer_ready_pipe[2];
    int peer_release_pipe[2];
    pid_t writer_child;
    pid_t peer_child;
    mylite_db *db;

    assert(mkdir(runtime_root, 0700) == 0);
    initialize_database(paths);
    datadir_path = path_join(database_path, "datadir");
    app_path = path_join(datadir_path, "app");
    frm_path = path_join(app_path, "ownerless_drop_crash.frm");
    ibd_path = path_join(app_path, "ownerless_drop_crash.ibd");

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_drop_crash ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_drop_crash VALUES (1, 10)");
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_drop_crash") == 10U);
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);

    assert(pipe(writer_ready_pipe) == 0);
    assert(pipe(peer_ready_pipe) == 0);
    assert(pipe(peer_release_pipe) == 0);

    peer_child = fork();
    assert(peer_child >= 0);
    if (peer_child == 0) {
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        close(writer_ready_pipe[0]);
        close(writer_ready_pipe[1]);
        hold_ownerless_open_until_released(
            paths,
            (child_pipes){
                .ready_write_fd = peer_ready_pipe[1],
                .release_read_fd = peer_release_pipe[0],
            }
        );
    }

    close(peer_ready_pipe[1]);
    close(peer_release_pipe[0]);
    wait_for_pipe(peer_ready_pipe[0]);

    writer_child = fork();
    assert(writer_child >= 0);
    if (writer_child == 0) {
        close(writer_ready_pipe[0]);
        close(peer_ready_pipe[0]);
        close(peer_release_pipe[1]);
        drop_table_until_dictionary_finish_fault(paths, writer_ready_pipe[1]);
    }

    close(writer_ready_pipe[1]);
    wait_for_pipe(writer_ready_pipe[0]);
    assert(kill(writer_child, SIGKILL) == 0);
    wait_for_signaled_child(writer_child, SIGKILL);
    if (assert_file_op_marker) {
        assert(read_concurrency_native_file_op_checkpoint_needed(database_path));
    }

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_drop_crash'"
        ) == 0U
    );
    assert(exec_status(db, "SELECT COUNT(*) FROM app.ownerless_drop_crash", NULL) != MYLITE_OK);
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);
    assert(read_concurrency_native_file_op_checkpoint_needed(database_path));

    signal_pipe(peer_release_pipe[1]);
    wait_for_child(peer_child);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_drop_crash'"
        ) == 0U
    );
    assert(exec_status(db, "SELECT COUNT(*) FROM app.ownerless_drop_crash", NULL) != MYLITE_OK);
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);
    assert(!read_concurrency_native_file_op_checkpoint_needed(database_path));

    remove_concurrency_shm(database_path);
    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_drop_crash'"
        ) == 0U
    );
    assert(exec_status(db, "SELECT COUNT(*) FROM app.ownerless_drop_crash", NULL) != MYLITE_OK);
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);

    db = open_database(paths, MYLITE_OPEN_READWRITE);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_drop_crash'"
        ) == 0U
    );
    assert(exec_status(db, "SELECT COUNT(*) FROM app.ownerless_drop_crash", NULL) != MYLITE_OK);
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);

    free(ibd_path);
    free(frm_path);
    free(app_path);
    free(datadir_path);
    free(database_path);
    free(runtime_root);
    remove_tree(root);
    free(root);
}

