static void run_ownerless_tx_stress_worker(
    open_database_paths paths,
    unsigned worker_id,
    child_pipes pipes
) {
    mylite_db *db;
    char sql[256];
    const unsigned rounds = ownerless_tx_stress_rounds();

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 30");
    exec_ok(db, "SET SESSION lock_wait_timeout = 30");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned round = 1U; round <= rounds; ++round) {
        const unsigned long long delta = ownerless_tx_stress_delta(worker_id, round);

        exec_ok(db, "START TRANSACTION");
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "UPDATE app.ownerless_tx_stress_%u "
                "SET value = value + %llu, version = version + 1 "
                "WHERE id = 1",
                worker_id,
                delta
            ) > 0
        );
        exec_ok(db, sql);
        exec_ok(db, "SAVEPOINT ownerless_tx_stress_sp");
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "UPDATE app.ownerless_tx_stress_%u "
                "SET value = value + %llu, version = version + 1 "
                "WHERE id = 2",
                worker_id,
                delta * 101ULL
            ) > 0
        );
        exec_ok(db, sql);
        exec_ok(db, "ROLLBACK TO SAVEPOINT ownerless_tx_stress_sp");
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "SELECT value FROM app.ownerless_tx_stress_%u WHERE id = 2",
                worker_id
            ) > 0
        );
        {
            const unsigned long long observed_after_rollback = query_unsigned(db, sql);
            if (observed_after_rollback != 0U) {
                fprintf(
                    stderr,
                    "ownerless tx stress rollback mismatch after rollback: "
                    "worker=%u round=%u value=%llu\n",
                    worker_id,
                    round,
                    observed_after_rollback
                );
                fflush(stderr);
            }
            assert(observed_after_rollback == 0U);
        }
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "UPDATE app.ownerless_tx_stress_%u "
                "SET value = value + %llu, version = version + 1 "
                "WHERE id = 3",
                worker_id,
                delta * 2ULL
            ) > 0
        );
        exec_ok(db, sql);
        exec_ok(db, "RELEASE SAVEPOINT ownerless_tx_stress_sp");
        if (round % 5U == 0U || round == rounds) {
            unsigned long long observed_rolled_back_value;

            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "SELECT value FROM app.ownerless_tx_stress_%u WHERE id = 2",
                    worker_id
                ) > 0
            );
            observed_rolled_back_value = query_unsigned(db, sql);
            if (observed_rolled_back_value != 0U) {
                fprintf(
                    stderr,
                    "ownerless tx stress rollback mismatch before commit: "
                    "worker=%u round=%u value=%llu\n",
                    worker_id,
                    round,
                    observed_rolled_back_value
                );
                fflush(stderr);
            }
            assert(observed_rolled_back_value == 0U);
        }
        exec_ok(db, "COMMIT");
    }

    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_checksum_stress_writer(
    open_database_paths paths,
    unsigned worker_id,
    child_pipes pipes
) {
    mylite_db *db;
    char sql[256];
    const unsigned rounds = ownerless_checksum_stress_rounds();

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 1");
    exec_ok(db, "SET SESSION lock_wait_timeout = 0");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned round = 1U; round <= rounds; ++round) {
        const unsigned row_id = ownerless_checksum_stress_row_id(worker_id, round);
        const unsigned long long delta = ownerless_checksum_stress_delta(worker_id, round);
        int update_finished = 0;

        assert(
            snprintf(
                sql,
                sizeof(sql),
                "UPDATE app.ownerless_checksum_stress "
                "SET value = value + %llu, version = version + 1 "
                "WHERE id = %u",
                delta,
                row_id
            ) > 0
        );
        for (unsigned attempt = 1U; attempt <= MYLITE_TEST_CHECKSUM_STRESS_MAX_ATTEMPTS;
             ++attempt) {
            if (ownerless_checksum_stress_exec_retryable(db, sql, worker_id, round, attempt)) {
                assert(mylite_changes(db) == 1);
                update_finished = 1;
                break;
            }
            ownerless_checksum_stress_retry_pause(worker_id, round, attempt);
        }
        if (!update_finished) {
            fprintf(
                stderr,
                "ownerless checksum stress exhausted retries: worker=%u round=%u sql=%s\n",
                worker_id,
                round,
                sql
            );
            fflush(stderr);
        }
        assert(update_finished);

        if (round % 17U == 0U || round == rounds) {
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "SELECT COUNT(*) FROM app.ownerless_checksum_stress "
                    "WHERE worker = %u AND version > 0",
                    worker_id
                ) > 0
            );
            assert(query_unsigned(db, sql) >= 1U);
        }
    }

    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_prepared_checksum_stress_writer(
    open_database_paths paths,
    unsigned worker_id,
    child_pipes pipes
) {
    mylite_db *db;
    mylite_stmt *stmt = NULL;
    const char *tail = NULL;
    char sql[256];
    const unsigned rounds = ownerless_checksum_stress_rounds();

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 1");
    exec_ok(db, "SET SESSION lock_wait_timeout = 0");
    assert(
        mylite_prepare(
            db,
            "UPDATE app.ownerless_checksum_stress "
            "SET value = value + ?, version = version + 1 "
            "WHERE id = ?",
            MYLITE_NUL_TERMINATED,
            &stmt,
            &tail
        ) == MYLITE_OK
    );
    assert(stmt != NULL);
    assert(tail != NULL && *tail == '\0');
    assert(mylite_bind_parameter_count(stmt) == 2U);

    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned round = 1U; round <= rounds; ++round) {
        const unsigned row_id = ownerless_checksum_stress_row_id(worker_id, round);
        const unsigned long long delta = ownerless_checksum_stress_delta(worker_id, round);
        int update_finished = 0;

        for (unsigned attempt = 1U; attempt <= MYLITE_TEST_CHECKSUM_STRESS_MAX_ATTEMPTS;
             ++attempt) {
            int step_result;

            assert(mylite_bind_uint64(stmt, 1, delta) == MYLITE_OK);
            assert(mylite_bind_int64(stmt, 2, (long long)row_id) == MYLITE_OK);
            step_result = mylite_step(stmt);
            if (step_result == MYLITE_DONE) {
                assert(mylite_changes(db) == 1);
                assert(mylite_reset(stmt) == MYLITE_OK);
                update_finished = 1;
                break;
            }
            if (ownerless_checksum_stress_step_retryable(
                    db,
                    stmt,
                    step_result,
                    worker_id,
                    round,
                    attempt
                )) {
                ownerless_checksum_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            fprintf(
                stderr,
                "ownerless prepared checksum stress unexpected step failure: "
                "worker=%u round=%u attempt=%u result=%d errcode=%d mariadb_errno=%u "
                "message=%s\n",
                worker_id,
                round,
                attempt,
                step_result,
                mylite_errcode(db),
                mylite_mariadb_errno(db),
                mylite_errmsg(db)
            );
            fflush(stderr);
            assert(0);
        }
        if (!update_finished) {
            fprintf(
                stderr,
                "ownerless prepared checksum stress exhausted retries: worker=%u round=%u\n",
                worker_id,
                round
            );
            fflush(stderr);
        }
        assert(update_finished);

        if (round % 17U == 0U || round == rounds) {
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "SELECT COUNT(*) FROM app.ownerless_checksum_stress "
                    "WHERE worker = %u AND version > 0",
                    worker_id
                ) > 0
            );
            assert(query_unsigned(db, sql) >= 1U);
        }
    }

    assert(mylite_finalize(stmt) == MYLITE_OK);
    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_checksum_stress_reader(open_database_paths paths, child_pipes pipes) {
    mylite_db *db;
    unsigned long long previous_sum = 0U;
    const unsigned rounds = ownerless_checksum_stress_rounds();
    unsigned long long expected_sum = 0U;
    unsigned long long expected_versions = 0U;
    unsigned long long expected_weighted_sum = 0U;

    ownerless_checksum_stress_expected(
        rounds,
        &expected_sum,
        &expected_versions,
        &expected_weighted_sum
    );

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 30");
    exec_ok(db, "SET SESSION lock_wait_timeout = 30");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned iteration = 0U; iteration < rounds * MYLITE_TEST_CHECKSUM_STRESS_WORKER_COUNT;
         ++iteration) {
        const unsigned long long sum =
            query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_checksum_stress");
        const unsigned long long versions =
            query_unsigned(db, "SELECT SUM(version) FROM app.ownerless_checksum_stress");

        assert(sum >= previous_sum);
        assert(sum <= expected_sum);
        assert(versions <= expected_versions);
        previous_sum = sum;
        sleep_microseconds(1000U);
    }

    (void)expected_weighted_sum;
    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_random_tx_stress_worker(
    open_database_paths paths,
    unsigned worker_id,
    child_pipes pipes
) {
    mylite_db *db;
    char sql[256];
    const unsigned rounds = ownerless_random_tx_stress_rounds();

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 1");
    exec_ok(db, "SET SESSION lock_wait_timeout = 1");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned round = 1U; round <= rounds; ++round) {
        int round_finished = 0;

        for (unsigned attempt = 1U; attempt <= MYLITE_TEST_RANDOM_TX_STRESS_MAX_ATTEMPTS;
             ++attempt) {
            unsigned rows[3];
            const int rollback_transaction =
                ownerless_random_tx_stress_rolls_back_transaction(worker_id, round);
            const int rollback_savepoint =
                ownerless_random_tx_stress_rolls_back_savepoint(worker_id, round);
            unsigned long long before_values[3];
            unsigned long long before_versions[3];

            ownerless_random_tx_stress_rows(worker_id, round, rows);
            assert(query_unsigned(db, "SELECT @@in_transaction") == 0U);
            ownerless_random_tx_stress_capture_rows(db, rows, before_values, before_versions);
            exec_ok(db, "START TRANSACTION");
            assert(query_unsigned(db, "SELECT @@in_transaction") == 1U);
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_random_tx_stress "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    ownerless_random_tx_stress_delta(worker_id, round, 0U),
                    rows[0]
                ) > 0
            );
            if (!ownerless_random_tx_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    0U
                )) {
                exec_ok(db, "ROLLBACK");
                assert_ownerless_random_tx_stress_rows_unchanged_after_rollback(
                    db,
                    worker_id,
                    round,
                    attempt,
                    "retry-phase-0",
                    rows,
                    before_values,
                    before_versions
                );
                ownerless_random_tx_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(mylite_changes(db) == 1);
            exec_ok(db, "SAVEPOINT ownerless_random_tx_sp");
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_random_tx_stress "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    ownerless_random_tx_stress_delta(worker_id, round, 1U),
                    rows[1]
                ) > 0
            );
            if (!ownerless_random_tx_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    1U
                )) {
                exec_ok(db, "ROLLBACK");
                assert_ownerless_random_tx_stress_rows_unchanged_after_rollback(
                    db,
                    worker_id,
                    round,
                    attempt,
                    "retry-phase-1",
                    rows,
                    before_values,
                    before_versions
                );
                ownerless_random_tx_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(mylite_changes(db) == 1);
            if (rollback_savepoint) {
                exec_ok(db, "ROLLBACK TO SAVEPOINT ownerless_random_tx_sp");
            }
            exec_ok(db, "RELEASE SAVEPOINT ownerless_random_tx_sp");
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_random_tx_stress "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    ownerless_random_tx_stress_delta(worker_id, round, 2U),
                    rows[2]
                ) > 0
            );
            if (!ownerless_random_tx_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    2U
                )) {
                exec_ok(db, "ROLLBACK");
                assert_ownerless_random_tx_stress_rows_unchanged_after_rollback(
                    db,
                    worker_id,
                    round,
                    attempt,
                    "retry-phase-2",
                    rows,
                    before_values,
                    before_versions
                );
                ownerless_random_tx_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(mylite_changes(db) == 1);
            if (round % 7U == 0U || round == rounds) {
                assert(
                    query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_random_tx_stress") ==
                    MYLITE_TEST_RANDOM_TX_STRESS_ROW_COUNT
                );
            }
            const char *transaction_end_sql = rollback_transaction ? "ROLLBACK" : "COMMIT";

            assert(query_unsigned(db, "SELECT @@in_transaction") == 1U);
            exec_ok(db, transaction_end_sql);
            if (rollback_transaction) {
                assert_ownerless_random_tx_stress_rows_unchanged_after_rollback(
                    db,
                    worker_id,
                    round,
                    attempt,
                    "final",
                    rows,
                    before_values,
                    before_versions
                );
            }
            if (ownerless_random_tx_stress_trace_retries()) {
                fprintf(
                    stderr,
                    "ownerless random tx stress round end: worker=%u round=%u "
                    "attempt=%u end=%s rows=%u,%u,%u rollback_savepoint=%d\n",
                    worker_id,
                    round,
                    attempt,
                    transaction_end_sql,
                    rows[0],
                    rows[1],
                    rows[2],
                    rollback_savepoint
                );
                fflush(stderr);
            }
            round_finished = 1;
            break;
        }

        if (!round_finished) {
            fprintf(
                stderr,
                "ownerless random tx stress exhausted retries: worker=%u round=%u\n",
                worker_id,
                round
            );
            fflush(stderr);
        }
        assert(round_finished);
    }

    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_random_tx_stress_reader(open_database_paths paths, child_pipes pipes) {
    mylite_db *db;
    unsigned long long previous_sum = 0U;
    ownerless_random_tx_reader_values previous_rows = {{0}, {0}, 0U};
    const unsigned rounds = ownerless_random_tx_stress_rounds();
    unsigned long long expected_sum = 0U;
    unsigned long long expected_versions = 0U;
    unsigned long long expected_weighted_sum = 0U;

    ownerless_random_tx_stress_expected(
        rounds,
        &expected_sum,
        &expected_versions,
        &expected_weighted_sum
    );

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 30");
    exec_ok(db, "SET SESSION lock_wait_timeout = 30");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned iteration = 0U; iteration < rounds * MYLITE_TEST_RANDOM_TX_STRESS_WORKER_COUNT;
         ++iteration) {
        ownerless_random_tx_reader_values rows = {{0}, {0}, 0U};
        char *errmsg = NULL;
        unsigned long long sum = 0U;
        unsigned long long versions = 0U;
        unsigned long long weighted_sum = 0U;

        assert(
            mylite_exec(
                db,
                "SELECT id, value, version FROM app.ownerless_random_tx_stress ORDER BY id",
                capture_ownerless_random_tx_reader_values,
                &rows,
                &errmsg
            ) == MYLITE_OK
        );
        assert(errmsg == NULL);
        assert(rows.row_count == MYLITE_TEST_RANDOM_TX_STRESS_ROW_COUNT);
        for (unsigned row_id = 1U; row_id <= MYLITE_TEST_RANDOM_TX_STRESS_ROW_COUNT; ++row_id) {
            sum += rows.values[row_id];
            versions += rows.versions[row_id];
            weighted_sum += row_id * rows.values[row_id];
        }

        if (sum < previous_sum || sum > expected_sum || versions > expected_versions ||
            weighted_sum > expected_weighted_sum) {
            fprintf(
                stderr,
                "ownerless random tx stress reader mismatch: iteration=%u "
                "sum=%llu previous_sum=%llu expected_sum=%llu versions=%llu/%llu "
                "weighted=%llu/%llu\n",
                iteration,
                sum,
                previous_sum,
                expected_sum,
                versions,
                expected_versions,
                weighted_sum,
                expected_weighted_sum
            );
            for (unsigned row_id = 1U; row_id <= MYLITE_TEST_RANDOM_TX_STRESS_ROW_COUNT; ++row_id) {
                if (rows.values[row_id] != previous_rows.values[row_id] ||
                    rows.versions[row_id] != previous_rows.versions[row_id]) {
                    fprintf(
                        stderr,
                        "ownerless random tx stress reader row changed: "
                        "iteration=%u id=%u value=%llu previous_value=%llu "
                        "version=%llu previous_version=%llu\n",
                        iteration,
                        row_id,
                        rows.values[row_id],
                        previous_rows.values[row_id],
                        rows.versions[row_id],
                        previous_rows.versions[row_id]
                    );
                }
            }
            fflush(stderr);
        }
        assert(sum >= previous_sum);
        assert(sum <= expected_sum);
        assert(versions <= expected_versions);
        assert(weighted_sum <= expected_weighted_sum);
        previous_sum = sum;
        previous_rows = rows;
        sleep_microseconds(1000U);
    }

    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static void run_ownerless_fk_graph_stress_worker(
    open_database_paths paths,
    unsigned worker_id,
    child_pipes pipes
) {
    mylite_db *db;
    char sql[512];
    const unsigned rounds = ownerless_fk_graph_stress_rounds();
    unsigned cascade_root = ownerless_fk_graph_stress_initial_id(worker_id, 1U);
    unsigned setnull_root = ownerless_fk_graph_stress_initial_id(worker_id, 2U);
    const unsigned restrict_root = ownerless_fk_graph_stress_initial_id(worker_id, 3U);

    db = open_database(paths, MYLITE_OPEN_READWRITE | MYLITE_OPEN_OWNERLESS_RW);
    exec_ok(db, "SET SESSION innodb_lock_wait_timeout = 30");
    exec_ok(db, "SET SESSION lock_wait_timeout = 30");
    signal_pipe(pipes.ready_write_fd);
    wait_for_pipe(pipes.release_read_fd);

    for (unsigned round = 1U; round <= rounds; ++round) {
        const unsigned long long delta = ownerless_fk_graph_stress_delta(worker_id, round);
        int round_finished = 0;

        for (unsigned attempt = 1U; attempt <= MYLITE_TEST_FK_GRAPH_STRESS_MAX_ATTEMPTS;
             ++attempt) {
            const unsigned next_cascade_root = cascade_root + 1U;
            const unsigned next_setnull_root = setnull_root + 1U;

            exec_ok(db, "START TRANSACTION");
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_root "
                    "SET id = %u, value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    next_cascade_root,
                    delta,
                    cascade_root
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "cascade-root-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_root "
                    "SET id = %u, value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    next_setnull_root,
                    delta,
                    setnull_root
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "setnull-root-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_root "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE id = %u",
                    delta,
                    restrict_root
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "restrict-root-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_cascade_child "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE worker_id = %u",
                    delta,
                    worker_id
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "cascade-child-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_setnull_child "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE worker_id = %u",
                    delta,
                    worker_id
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "setnull-child-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "UPDATE app.ownerless_fk_graph_restrict_child "
                    "SET value = value + %llu, version = version + 1 "
                    "WHERE worker_id = %u",
                    delta,
                    worker_id
                ) > 0
            );
            if (!ownerless_fk_graph_stress_exec_retryable(
                    db,
                    sql,
                    worker_id,
                    round,
                    attempt,
                    "restrict-child-update",
                    cascade_root,
                    setnull_root,
                    restrict_root
                )) {
                exec_ok(db, "ROLLBACK");
                ownerless_fk_graph_stress_retry_pause(worker_id, round, attempt);
                continue;
            }
            exec_ok(db, "COMMIT");
            cascade_root = next_cascade_root;
            setnull_root = next_setnull_root;
            round_finished = 1;
            break;
        }

        if (!round_finished) {
            fprintf(
                stderr,
                "ownerless fk graph stress exhausted retries: worker=%u round=%u\n",
                worker_id,
                round
            );
            fflush(stderr);
        }
        assert(round_finished);

        if (round % 4U == 0U || round == rounds) {
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "DELETE FROM app.ownerless_fk_graph_root WHERE id = %u",
                    restrict_root
                ) > 0
            );
            ownerless_fk_graph_stress_expect_mariadb_error(
                db,
                sql,
                MYLITE_TEST_ROW_IS_REFERENCED_ERRNO,
                worker_id,
                round
            );
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "INSERT INTO app.ownerless_fk_graph_cascade_child "
                    "VALUES (%u, %u, %u, 0, 0)",
                    ownerless_fk_graph_stress_initial_id(worker_id, 1U) + 70000U + round,
                    worker_id,
                    ownerless_fk_graph_stress_initial_id(worker_id, 1U) + 90000U + round
                ) > 0
            );
            ownerless_fk_graph_stress_expect_mariadb_error(
                db,
                sql,
                MYLITE_TEST_NO_REFERENCED_ROW_ERRNO,
                worker_id,
                round
            );
        }
    }

    for (unsigned attempt = 1U; attempt <= MYLITE_TEST_FK_GRAPH_STRESS_MAX_ATTEMPTS; ++attempt) {
        exec_ok(db, "START TRANSACTION");
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "DELETE FROM app.ownerless_fk_graph_root WHERE id = %u",
                setnull_root
            ) > 0
        );
        if (!ownerless_fk_graph_stress_exec_retryable(
                db,
                sql,
                worker_id,
                rounds,
                attempt,
                "setnull-root-delete",
                cascade_root,
                setnull_root,
                restrict_root
            )) {
            exec_ok(db, "ROLLBACK");
            ownerless_fk_graph_stress_retry_pause(worker_id, rounds, attempt);
            continue;
        }
        exec_ok(db, "COMMIT");
        setnull_root = 0U;
        break;
    }
    if (setnull_root != 0U) {
        fprintf(
            stderr,
            "ownerless fk graph stress exhausted set-null delete retries: worker=%u\n",
            worker_id
        );
        fflush(stderr);
    }
    assert(setnull_root == 0U);

    assert(mylite_close(db) == MYLITE_OK);
    _exit(0);
}

static unsigned ownerless_stress_iterations(void) {
    return ownerless_unsigned_env(
        "MYLITE_OWNERLESS_STRESS_ITERATIONS",
        MYLITE_TEST_STRESS_ITERATIONS,
        MYLITE_TEST_STRESS_ITERATIONS_MAX
    );
}

static unsigned ownerless_stress_reader_polls(void) {
    return ownerless_unsigned_env(
        "MYLITE_OWNERLESS_STRESS_READER_POLLS",
        MYLITE_TEST_STRESS_READER_POLLS,
        MYLITE_TEST_STRESS_READER_POLLS_MAX
    );
}

static unsigned ownerless_ddl_stress_rounds(void) {
    return ownerless_unsigned_env(
        "MYLITE_OWNERLESS_DDL_STRESS_ROUNDS",
        MYLITE_TEST_DDL_STRESS_ROUNDS,
        MYLITE_TEST_DDL_STRESS_ROUNDS_MAX
    );
}

static unsigned ownerless_ddl_stress_lock_wait_timeout_seconds(void) {
    const char *value = getenv("MYLITE_OWNERLESS_DDL_STRESS_LOCK_WAIT_TIMEOUT");
    char *end = NULL;
    unsigned long parsed;

    if (value == NULL || value[0] == '\0') {
        return MYLITE_TEST_DDL_STRESS_LOCK_WAIT_TIMEOUT_SECONDS;
    }

    errno = 0;
    parsed = strtoul(value, &end, 10);
    if (errno != 0 || end == value || *end != '\0' ||
        parsed > MYLITE_TEST_DDL_STRESS_LOCK_WAIT_TIMEOUT_SECONDS_MAX) {
        fprintf(
            stderr,
            "invalid MYLITE_OWNERLESS_DDL_STRESS_LOCK_WAIT_TIMEOUT=%s; expected 0..%u\n",
            value,
            MYLITE_TEST_DDL_STRESS_LOCK_WAIT_TIMEOUT_SECONDS_MAX
        );
        fflush(stderr);
        assert(0);
    }
    return (unsigned)parsed;
}

static int ownerless_ddl_stress_hold_dictionary_statement_lock(const char *database_path) {
    char *concurrency_path = path_join(database_path, "concurrency");
    char *statement_lock_path = path_join(concurrency_path, "mylite-statements.lock");
    struct flock lock = {
        .l_type = F_WRLCK,
        .l_whence = SEEK_SET,
        .l_start = MYLITE_TEST_DDL_STRESS_DICTIONARY_STATEMENT_LOCK_START,
        .l_len = MYLITE_TEST_DDL_STRESS_DICTIONARY_STATEMENT_LOCK_LENGTH,
    };
    int lock_fd;

    lock_fd = open(statement_lock_path, O_RDWR | O_CREAT | O_CLOEXEC, 0600);
    assert(lock_fd >= 0);
    assert(fcntl(lock_fd, F_SETLK, &lock) == 0);
    free(statement_lock_path);
    free(concurrency_path);
    return lock_fd;
}

static void ownerless_ddl_stress_release_dictionary_statement_lock(int lock_fd) {
    struct flock lock = {
        .l_type = F_UNLCK,
        .l_whence = SEEK_SET,
        .l_start = MYLITE_TEST_DDL_STRESS_DICTIONARY_STATEMENT_LOCK_START,
        .l_len = MYLITE_TEST_DDL_STRESS_DICTIONARY_STATEMENT_LOCK_LENGTH,
    };

    assert(lock_fd >= 0);
    assert(fcntl(lock_fd, F_SETLK, &lock) == 0);
    assert(close(lock_fd) == 0);
}

