static void assert_ownerless_recreated_tablespace_replay_state(
    open_database_paths paths,
    unsigned flags,
    const char *database_path
) {
    char *datadir_path = path_join(database_path, "datadir");
    char *app_path = path_join(datadir_path, "app");
    char *frm_path = path_join(app_path, "ownerless_recreated_replay.frm");
    char *ibd_path = path_join(app_path, "ownerless_recreated_replay.ibd");
    mylite_db *db = open_database(paths, flags);

    if ((flags & MYLITE_OPEN_OWNERLESS_RW) != 0U) {
        assert_concurrency_wal_checkpointed(database_path);
    }
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql") == 30U);
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_recreated_replay'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.columns "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_recreated_replay' "
            "AND column_name = 'generation'"
        ) == 1U
    );
    assert(query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_recreated_replay") == 3U);
    assert(query_unsigned(db, "SELECT SUM(id) FROM app.ownerless_recreated_replay") == 306U);
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_recreated_replay") == 2109U);
    assert(query_unsigned(db, "SELECT SUM(generation) FROM app.ownerless_recreated_replay") == 6U);
    assert(
        query_unsigned(db, "SELECT SUM(LENGTH(payload)) FROM app.ownerless_recreated_replay") ==
        12000U
    );
    assert(path_exists(frm_path));
    assert(path_exists(ibd_path));
    assert(
        read_innodb_page_zero_space_id(ibd_path) ==
        (uint32_t)query_unsigned(
            db,
            "SELECT SPACE FROM information_schema.INNODB_SYS_TABLES "
            "WHERE NAME = 'app/ownerless_recreated_replay'"
        )
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert_concurrency_wal_checkpointed(database_path);

    free(ibd_path);
    free(frm_path);
    free(app_path);
    free(datadir_path);
}

