static void assert_ownerless_ddl_stress_state(
    open_database_paths paths,
    unsigned flags,
    unsigned long long expected_total
) {
    mylite_db *db = open_database(paths, flags);
    const unsigned long long observed_total =
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_sql");
    const unsigned long long remaining_stress_tables = query_unsigned(
        db,
        "SELECT COUNT(*) FROM information_schema.tables "
        "WHERE table_schema = 'app' "
        "AND table_name >= 'ownerless_ddl_stress_' "
        "AND table_name < 'ownerless_ddl_stress`'"
    );

    if (observed_total != expected_total || remaining_stress_tables != 0U) {
        fprintf(
            stderr,
            "ownerless ddl stress mismatch: flags=%u total=%llu/%llu tables=%llu/0\n",
            flags,
            observed_total,
            expected_total,
            remaining_stress_tables
        );
    }
    assert(observed_total == expected_total);
    assert(remaining_stress_tables == 0U);
    assert(mylite_close(db) == MYLITE_OK);
}

static void assert_ownerless_table_idempotent_ddl_state(
    open_database_paths paths,
    unsigned flags,
    const char *database_path
) {
    char *datadir_path = path_join(database_path, "datadir");
    char *app_path = path_join(datadir_path, "app");
    char *frm_path = path_join(app_path, "ownerless_table_idempotent.frm");
    char *ibd_path = path_join(app_path, "ownerless_table_idempotent.ibd");
    mylite_db *db = open_database(paths, flags);

    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent'"
        ) == 0U
    );
    assert(
        exec_status(db, "SELECT COUNT(*) FROM app.ownerless_table_idempotent", NULL) != MYLITE_OK
    );
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    exec_ok(
        db,
        "CREATE TABLE app.ownerless_table_idempotent ("
        "id INT NOT NULL PRIMARY KEY, "
        "value INT NOT NULL"
        ") ENGINE=InnoDB"
    );
    exec_ok(db, "INSERT INTO app.ownerless_table_idempotent VALUES (1, 11)");
    assert(query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_table_idempotent") == 11U);
    exec_ok(db, "DROP TABLE app.ownerless_table_idempotent");
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_table_idempotent'"
        ) == 0U
    );
    assert(!path_exists(frm_path));
    assert(!path_exists(ibd_path));
    assert(mylite_close(db) == MYLITE_OK);

    free(ibd_path);
    free(frm_path);
    free(app_path);
    free(datadir_path);
}

