static void assert_ownerless_compressed_row_format_ddl_state(
    open_database_paths paths,
    unsigned flags
) {
    mylite_db *db = open_database(paths, flags);

    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.INNODB_SYS_TABLES "
            "WHERE NAME = 'app/ownerless_compressed_row_format_base' "
            "AND ROW_FORMAT = 'Compressed'"
        ) == 1U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = 'ownerless_compressed_row_format_base' "
            "AND row_format = 'Compressed'"
        ) == 1U
    );
    assert(
        query_unsigned(db, "SELECT COUNT(*) FROM app.ownerless_compressed_row_format_base") == 3U
    );
    assert(
        query_unsigned(db, "SELECT SUM(value) FROM app.ownerless_compressed_row_format_base") == 60U
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(LENGTH(payload)) FROM app.ownerless_compressed_row_format_base"
        ) == 3U * MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES
    );
    assert(
        query_unsigned(
            db,
            "SELECT SUM(ASCII(SUBSTRING(payload, 1, 1))) "
            "FROM app.ownerless_compressed_row_format_base"
        ) == (2U * (unsigned)'a') + (unsigned)'c'
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_compressed_row_format_base "
            "WHERE note LIKE 'before-%'"
        ) == 2U
    );
    assert(
        query_unsigned(
            db,
            "SELECT COUNT(*) FROM app.ownerless_compressed_row_format_base "
            "WHERE note = 'after'"
        ) == 1U
    );
    assert(mylite_close(db) == MYLITE_OK);
    assert(count_ownerless_compressed_row_format_zblob_pages(paths.database_path) > 0U);
}

static void assert_ownerless_compressed_row_format_key_block_sql_state(
    mylite_db *db,
    const char *table_name
) {
    char sql[512];

    assert(
        snprintf(
            sql,
            sizeof(sql),
            "SELECT COUNT(*) FROM information_schema.INNODB_SYS_TABLES "
            "WHERE NAME = 'app/%s' "
            "AND ROW_FORMAT = 'Compressed'",
            table_name
        ) > 0
    );
    assert(query_unsigned(db, sql) == 1U);
    assert(
        snprintf(
            sql,
            sizeof(sql),
            "SELECT COUNT(*) FROM information_schema.tables "
            "WHERE table_schema = 'app' "
            "AND table_name = '%s' "
            "AND row_format = 'Compressed'",
            table_name
        ) > 0
    );
    assert(query_unsigned(db, sql) == 1U);
    assert(snprintf(sql, sizeof(sql), "SELECT COUNT(*) FROM app.%s", table_name) > 0);
    assert(query_unsigned(db, sql) == 3U);
    assert(snprintf(sql, sizeof(sql), "SELECT SUM(value) FROM app.%s", table_name) > 0);
    assert(query_unsigned(db, sql) == 3U);
    assert(snprintf(sql, sizeof(sql), "SELECT SUM(LENGTH(payload)) FROM app.%s", table_name) > 0);
    assert(query_unsigned(db, sql) == 3U * MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES);
    assert(
        snprintf(
            sql,
            sizeof(sql),
            "SELECT SUM(ASCII(SUBSTRING(payload, 1, 1))) "
            "FROM app.%s",
            table_name
        ) > 0
    );
    assert(query_unsigned(db, sql) == (2U * (unsigned)'a') + (unsigned)'c');
}

