    free(child_ibd_path);
    free(child_frm_path);
    free(parent_moved_ibd_path);
    free(parent_moved_frm_path);
    free(parent_tmp_ibd_path);
    free(parent_tmp_frm_path);
    free(parent_ibd_path);
    free(parent_frm_path);
