static void assert_commit_race_total(
    open_database_paths paths,
    unsigned flags,
    unsigned long long expected_sum
) {
    mylite_db *db = open_database(paths, flags);
    char sql[192];
    unsigned long long table_values[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT] = {0U};
    unsigned long long current_values[MYLITE_TEST_COMMIT_RACE_WORKER_COUNT] = {0U};
    unsigned long long actual_sum = 0U;

    if ((flags & MYLITE_OPEN_OWNERLESS_RW) != 0U) {
        const uint64_t checkpoint_latest_lsn =
            read_concurrency_checkpoint_latest_lsn(paths.database_path);
        const uint64_t checkpoint_visible_lsn =
            read_concurrency_checkpoint_visible_lsn(paths.database_path);
        if (checkpoint_latest_lsn != 0U && checkpoint_visible_lsn == 0U) {
            fprintf(
                stderr,
                "expected ownerless commit-race checkpoint visible LSN after ownerless open, "
                "latest=%llu visible=%llu\n",
                (unsigned long long)checkpoint_latest_lsn,
                (unsigned long long)checkpoint_visible_lsn
            );
        }
        assert(checkpoint_latest_lsn == 0U || checkpoint_visible_lsn != 0U);
    }

    for (unsigned table_id = 1U; table_id <= MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++table_id) {
        assert(
            snprintf(
                sql,
                sizeof(sql),
                "SELECT SUM(value) FROM app.ownerless_commit_race_%u",
                table_id
            ) > 0
        );
        table_values[table_id - 1U] = query_unsigned(db, sql);
        actual_sum += table_values[table_id - 1U];
    }
    if (actual_sum != expected_sum) {
        for (unsigned table_id = 1U; table_id <= MYLITE_TEST_COMMIT_RACE_WORKER_COUNT; ++table_id) {
            assert(
                snprintf(
                    sql,
                    sizeof(sql),
                    "SELECT value FROM app.ownerless_commit_race_%u WHERE id = 1 FOR UPDATE",
                    table_id
                ) > 0
            );
            current_values[table_id - 1U] = query_unsigned(db, sql);
        }
        fprintf(
            stderr,
            "expected ownerless commit-race total %llu with flags %u, got %llu "
            "values=%llu,%llu,%llu,%llu current=%llu,%llu,%llu,%llu\n",
            expected_sum,
            flags,
            actual_sum,
            table_values[0],
            table_values[1],
            table_values[2],
            table_values[3],
            current_values[0],
            current_values[1],
            current_values[2],
            current_values[3]
        );
    }
    assert(actual_sum == expected_sum);
    assert(mylite_close(db) == MYLITE_OK);
}

static uint64_t assert_commit_race_recovery_anchors(
    const char *database_path,
    uint64_t minimum_visible_lsn
) {
    assert_concurrency_wal_has_page_versions_or_checkpoint(database_path);
    if (!concurrency_wal_is_checkpointed(database_path)) {
        assert_concurrency_page_index_has_entries(database_path);
    }

    const uint64_t checkpoint_visible_lsn = read_concurrency_checkpoint_visible_lsn(database_path);
    if (checkpoint_visible_lsn < minimum_visible_lsn || checkpoint_visible_lsn == 0U) {
        fprintf(
            stderr,
            "expected ownerless commit-race checkpoint visible LSN >= %llu, got %llu\n",
            (unsigned long long)minimum_visible_lsn,
            (unsigned long long)checkpoint_visible_lsn
        );
    }
    assert(checkpoint_visible_lsn >= minimum_visible_lsn);
    assert(checkpoint_visible_lsn > 0U);
    assert(read_concurrency_redo_visible_lsn(database_path) >= checkpoint_visible_lsn);
    return checkpoint_visible_lsn;
}

