static void fill_ownerless_blob_pressure_payload(
    unsigned char *payload,
    size_t payload_size,
    unsigned row,
    unsigned char first_byte,
    unsigned salt
) {
    uint32_t state = 0x9e3779b9U ^ (row * 0x85ebca6bU) ^ (salt * 0xc2b2ae35U);

    assert(payload_size > 0U);
    payload[0] = first_byte;
    for (size_t index = 1U; index < payload_size; ++index) {
        state ^= state << 13U;
        state ^= state >> 17U;
        state ^= state << 5U;
        payload[index] = (unsigned char)(state >> 24U);
    }
}

static void insert_ownerless_compressed_row_format_row(
    mylite_db *db,
    unsigned row,
    unsigned value,
    const char *note,
    unsigned char first_byte
) {
    mylite_stmt *stmt = NULL;
    const char *tail = NULL;
    unsigned char *payload = malloc(MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES);

    assert(payload != NULL);
    fill_ownerless_blob_pressure_payload(
        payload,
        MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES,
        row,
        first_byte,
        0x1fU
    );
    assert(
        mylite_prepare(
            db,
            "INSERT INTO app.ownerless_compressed_row_format_base "
            "(id, value, note, payload) VALUES (?, ?, ?, ?)",
            MYLITE_NUL_TERMINATED,
            &stmt,
            &tail
        ) == MYLITE_OK
    );
    assert(stmt != NULL);
    assert(tail != NULL && *tail == '\0');
    assert(mylite_bind_parameter_count(stmt) == 4U);
    assert(mylite_bind_int64(stmt, 1, (long long)row) == MYLITE_OK);
    assert(mylite_bind_uint64(stmt, 2, value) == MYLITE_OK);
    assert(mylite_bind_text(stmt, 3, note, MYLITE_NUL_TERMINATED, MYLITE_STATIC) == MYLITE_OK);
    assert(
        mylite_bind_blob(
            stmt,
            4,
            payload,
            MYLITE_TEST_BLOB_PAGE_PRESSURE_PAYLOAD_BYTES,
            MYLITE_STATIC
        ) == MYLITE_OK
    );
    assert(mylite_step(stmt) == MYLITE_DONE);
    assert(mylite_finalize(stmt) == MYLITE_OK);
    free(payload);
}

static off_t concurrency_wal_size(const char *database_path) {
    char *concurrency_path = path_join(database_path, "concurrency");
    char *wal_path = path_join(concurrency_path, "mylite-concurrency.wal");
    struct stat wal_stat;

    assert(stat(wal_path, &wal_stat) == 0);
    free(wal_path);
    free(concurrency_path);
    return wal_stat.st_size;
}

static int concurrency_wal_is_checkpointed(const char *database_path) {
    char *concurrency_path = path_join(database_path, "concurrency");
    char *wal_path = path_join(concurrency_path, "mylite-concurrency.wal");
    struct stat wal_stat;
    const off_t empty_log_end =
        MYLITE_TEST_CONCURRENCY_RECOVERY_HEADER_SIZE + MYLITE_TEST_PAGE_LOG_HEADER_SIZE;
    int exists;

    exists = stat(wal_path, &wal_stat) == 0;
    if (!exists) {
        assert(errno == ENOENT);
    }
    free(wal_path);
    free(concurrency_path);
    return !exists || wal_stat.st_size == empty_log_end;
}

static int wait_for_concurrency_wal_checkpointed(const char *database_path, unsigned timeout_ms) {
    const unsigned iterations = timeout_ms * 1000U / MYLITE_TEST_WAIT_POLL_INTERVAL_US;

    for (unsigned iteration = 0U; iteration <= iterations; ++iteration) {
        if (concurrency_wal_is_checkpointed(database_path)) {
            return 1;
        }
        sleep_microseconds(MYLITE_TEST_WAIT_POLL_INTERVAL_US);
    }
    return concurrency_wal_is_checkpointed(database_path);
}

static void assert_concurrency_wal_checkpointed(const char *database_path) {
    if (!concurrency_wal_is_checkpointed(database_path)) {
        fprintf(stderr, "ownerless page-version WAL was not checkpointed: %s\n", database_path);
        fflush(stderr);
        assert(0);
    }
}

static void assert_concurrency_wal_checkpointed_eventually(const char *database_path) {
    if (!wait_for_concurrency_wal_checkpointed(database_path, 5000U)) {
        fprintf(stderr, "ownerless page-version WAL was not checkpointed: %s\n", database_path);
        fflush(stderr);
        assert(0);
    }
}

static void assert_concurrency_wal_retained_for(const char *database_path, unsigned duration_ms) {
    const unsigned iterations = duration_ms * 1000U / MYLITE_TEST_WAIT_POLL_INTERVAL_US;

    for (unsigned iteration = 0U; iteration <= iterations; ++iteration) {
        if (concurrency_wal_is_checkpointed(database_path)) {
            fprintf(
                stderr,
                "ownerless page-version WAL checkpointed unexpectedly while retained state was "
                "required: %s\n",
                database_path
            );
            fflush(stderr);
            assert(0);
        }
        sleep_microseconds(MYLITE_TEST_WAIT_POLL_INTERVAL_US);
    }
    assert(!concurrency_wal_is_checkpointed(database_path));
}

