static int capture_first_column(void *ctx, int column_count, char **values, char **columns) {
    query_result *result = ctx;

    assert(column_count == 1);
    if (values[0] == NULL) {
        fprintf(
            stderr,
            "mylite query returned NULL first column: pid=%ld column=%s sql=%s\n",
            (long)getpid(),
            columns[0] != NULL ? columns[0] : "(unknown)",
            result->sql != NULL ? result->sql : "(unknown)"
        );
        fflush(stderr);
    }
    assert(values[0] != NULL);
    result->value = strtoull(values[0], NULL, 10);
    return 0;
}

static int capture_ownerless_stress_values(
    void *ctx,
    int column_count,
    char **values,
    char **columns
) {
    ownerless_stress_values *result = ctx;

    (void)columns;
    assert(result != NULL);
    assert(column_count == (int)MYLITE_TEST_STRESS_WRITER_COUNT);
    assert(result->row_count == 0U);
    for (unsigned index = 0U; index < MYLITE_TEST_STRESS_WRITER_COUNT; ++index) {
        assert(values[index] != NULL);
        result->values[index] = strtoull(values[index], NULL, 10);
    }
    result->row_count = 1U;
    return 0;
}

static int capture_ownerless_random_tx_reader_values(
    void *ctx,
    int column_count,
    char **values,
    char **columns
) {
    ownerless_random_tx_reader_values *result = ctx;

    (void)columns;
    assert(result != NULL);
    assert(column_count == 3);
    assert(values[0] != NULL);
    assert(values[1] != NULL);
    assert(values[2] != NULL);

    const unsigned long long id = strtoull(values[0], NULL, 10);
    assert(id >= 1U && id <= MYLITE_TEST_RANDOM_TX_STRESS_ROW_COUNT);
    result->values[id] = strtoull(values[1], NULL, 10);
    result->versions[id] = strtoull(values[2], NULL, 10);
    ++result->row_count;
    return 0;
}

static void assert_show_create_trigger_contains(
    mylite_db *db,
    const char *sql,
    const char *trigger_name,
    const char *statement_substring
) {
    show_create_trigger_expectation expectation = {
        .trigger_name = trigger_name,
        .statement_substring = statement_substring,
        .seen_rows = 0U,
    };
    char *errmsg = NULL;

    if (mylite_exec(db, sql, capture_show_create_trigger, &expectation, &errmsg) != MYLITE_OK) {
        fprintf(
            stderr,
            "mylite show trigger failed: pid=%ld sql=%s errcode=%d mariadb_errno=%u "
            "message=%s\n",
            (long)getpid(),
            sql,
            mylite_errcode(db),
            mylite_mariadb_errno(db),
            errmsg != NULL ? errmsg : mylite_errmsg(db)
        );
        fflush(stderr);
        if (errmsg != NULL) {
            mylite_free(errmsg);
        }
        assert(0);
    }
    assert(errmsg == NULL);
    assert(expectation.seen_rows == 1U);
}

static int capture_show_create_trigger(void *ctx, int column_count, char **values, char **columns) {
    show_create_trigger_expectation *expectation = ctx;

    assert(column_count >= 3);
    assert(strcmp(columns[0], "Trigger") == 0);
    assert(strcmp(columns[2], "SQL Original Statement") == 0);
    assert(values[0] != NULL);
    assert(values[2] != NULL);
    assert(strcmp(values[0], expectation->trigger_name) == 0);
    if (strstr(values[2], expectation->statement_substring) == NULL) {
        fprintf(
            stderr,
            "SHOW CREATE TRIGGER statement missing substring: trigger=%s statement=%s "
            "expected=%s\n",
            expectation->trigger_name,
            values[2],
            expectation->statement_substring
        );
        fflush(stderr);
    }
    assert(strstr(values[2], expectation->statement_substring) != NULL);
    ++expectation->seen_rows;
    return 0;
}

static uint64_t wait_for_concurrency_ownerless_write_waiting_count(
    const char *database_path,
    uint64_t expected_minimum,
    unsigned timeout_ms
) {
    const unsigned iterations = timeout_ms * 1000U / MYLITE_TEST_WAIT_POLL_INTERVAL_US;

    for (unsigned iteration = 0U; iteration <= iterations; ++iteration) {
        const uint64_t waiting_count =
            read_concurrency_innodb_lock_waiting_count(database_path) +
            read_concurrency_page_write_lock_waiting_count(database_path);
        if (expected_minimum == 0U) {
            if (waiting_count == 0U) {
                return waiting_count;
            }
        } else if (waiting_count >= expected_minimum) {
            return waiting_count;
        }
        sleep_microseconds(MYLITE_TEST_WAIT_POLL_INTERVAL_US);
    }
    return read_concurrency_innodb_lock_waiting_count(database_path) +
           read_concurrency_page_write_lock_waiting_count(database_path);
}

static uint64_t read_concurrency_innodb_lock_waiting_count(const char *database_path) {
    return read_concurrency_lock_waiting_count(
        database_path,
        MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SEGMENT_TYPE
    );
}

#if MYLITE_ENABLE_UNSAFE_OWNERLESS_TEST_HOOKS
static uint64_t wait_for_concurrency_innodb_table_waiting_count(
    const char *database_path,
    uint64_t expected_minimum,
    unsigned timeout_ms
) {
    const unsigned iterations = timeout_ms * 1000U / MYLITE_TEST_WAIT_POLL_INTERVAL_US;

    for (unsigned iteration = 0U; iteration <= iterations; ++iteration) {
        const uint64_t waiting_count = read_concurrency_innodb_table_waiting_count(database_path);
        if (expected_minimum == 0U) {
            if (waiting_count == 0U) {
                return waiting_count;
            }
        } else if (waiting_count >= expected_minimum) {
            return waiting_count;
        }
        sleep_microseconds(MYLITE_TEST_WAIT_POLL_INTERVAL_US);
    }
    return read_concurrency_innodb_table_waiting_count(database_path);
}

static uint64_t read_concurrency_innodb_table_waiting_count(const char *database_path) {
    char *concurrency_path = path_join(database_path, "concurrency");
    char *shm_path = path_join(concurrency_path, "mylite-concurrency.shm");
    unsigned char bytes[8];
    int fd = open(shm_path, O_RDONLY | O_CLOEXEC);
    uint64_t lock_offset;
    uint32_t slot_count;
    uint32_t slot_size;
    uint64_t waiting_count = 0U;

    assert(fd >= 0);
    lock_offset =
        read_concurrency_shm_segment_offset(fd, MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SEGMENT_TYPE);
    read_exact_at(
        fd,
        bytes,
        4U,
        (off_t)(lock_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SLOT_COUNT_OFFSET)
    );
    slot_count = read_le32(bytes);
    read_exact_at(
        fd,
        bytes,
        4U,
        (off_t)(lock_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SLOT_SIZE_OFFSET)
    );
    slot_size = read_le32(bytes);
    assert(slot_size == MYLITE_TEST_CONCURRENCY_INNODB_LOCK_REGISTRY_SLOT_SIZE);

    for (uint32_t index = 0U; index < slot_count; ++index) {
        const off_t slot_offset =
            (off_t)(lock_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_REGISTRY_HEADER_SIZE +
                    ((uint64_t)index * slot_size));
        uint32_t slot_state;
        uint32_t slot_kind;

        read_exact_at(
            fd,
            bytes,
            4U,
            slot_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SLOT_STATE_OFFSET
        );
        slot_state = read_le32(bytes);
        if (slot_state != MYLITE_TEST_CONCURRENCY_INNODB_LOCK_STATE_WAITING) {
            continue;
        }
        read_exact_at(
            fd,
            bytes,
            4U,
            slot_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_SLOT_KIND_OFFSET
        );
        slot_kind = read_le32(bytes);
        if (slot_kind == MYLITE_TEST_CONCURRENCY_INNODB_LOCK_KIND_TABLE) {
            ++waiting_count;
        }
    }

    assert(close(fd) == 0);
    free(shm_path);
    free(concurrency_path);
    return waiting_count;
}
#endif

static uint64_t read_concurrency_page_write_lock_waiting_count(const char *database_path) {
    return read_concurrency_lock_waiting_count(
        database_path,
        MYLITE_TEST_CONCURRENCY_PAGE_WRITE_LOCK_SEGMENT_TYPE
    );
}

static uint64_t read_concurrency_lock_waiting_count(
    const char *database_path,
    uint32_t segment_type
) {
    char *concurrency_path = path_join(database_path, "concurrency");
    char *shm_path = path_join(concurrency_path, "mylite-concurrency.shm");
    uint64_t lock_offset;
    unsigned char bytes[8];
    int fd = open(shm_path, O_RDONLY | O_CLOEXEC);

    assert(fd >= 0);
    lock_offset = read_concurrency_shm_segment_offset(fd, segment_type);
    read_exact_at(
        fd,
        bytes,
        sizeof(bytes),
        (off_t)(lock_offset + MYLITE_TEST_CONCURRENCY_INNODB_LOCK_WAITING_COUNT_OFFSET)
    );
    assert(close(fd) == 0);
    free(shm_path);
    free(concurrency_path);
    return read_le64(bytes);
}

